    const http = await testApp(AppModule, app => app.useGlobalPipes(new ValidationPipe({ transform: true })))
    await http.get("/users")
    await http.get("/users?page=3&limit=20")
    await http.get("/users?page=0&limit=500")
    await http.close()
}
main()

