type PaginatedResponse<T> = {
    data: T[]
    meta: { page: number; limit: number; total: number; totalPages: number; hasNext: boolean }
}

function paginate<T>(all: T[], page: number, limit: number): PaginatedResponse<T> {
    const total = all.length
    const totalPages = Math.ceil(total / limit)
    return { data: all.slice((page - 1) * limit, page * limit), meta: { page, limit, total, totalPages, hasNext: page < totalPages } }
}

const users = Array.from({ length: 7 }, (_, i) => ({ id: i + 1 }))
console.log(JSON.stringify(paginate(users, 1, 3)))
console.log(JSON.stringify(paginate(users, 3, 3)))

