import { Body, Controller, Module, Post, ValidationPipe } from "@nestjs/common"
import { registerDecorator, ValidationOptions } from "class-validator"

function IsUzPhone(options?: ValidationOptions) {
    return (object: object, propertyName: string) => registerDecorator({
        name: "isUzPhone", target: object.constructor, propertyName, options,
        validator: {
            validate: (v: unknown) => typeof v === "string" && /^\+998\d{9}$/.test(v),
            defaultMessage: () => `${propertyName} +998XXXXXXXXX ko'rinishida bo'lsin`,
        },
    })
}

class ContactDto { @IsUzPhone() phone: string }

@Controller("contacts")
class ContactsController {
    @Post() create(@Body() dto: ContactDto) { return dto }
}

@Module({ controllers: [ContactsController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule, app => app.useGlobalPipes(new ValidationPipe()))
    await http.post("/contacts", { phone: "+998901234567" })
    await http.post("/contacts", { phone: "90 123 45 67" })
    await http.close()
}
main()

import { Body, Controller, Module, Post, ValidationPipe } from "@nestjs/common"
import { IsString, MinLength, registerDecorator, ValidationArguments } from "class-validator"

function Match(property: string) {
    return (object: object, propertyName: string) => registerDecorator({
        name: "match", target: object.constructor, propertyName, constraints: [property],
        validator: {
            validate: (value: unknown, args: ValidationArguments) => value === (args.object as any)[args.constraints[0]],
            defaultMessage: (args: ValidationArguments) => `${propertyName} ${args.constraints[0]} bilan bir xil bo'lishi kerak`,
        },
    })
}

class ResetPasswordDto {
    @IsString() @MinLength(8) password: string
    @Match("password") confirmPassword: string
}

