import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, ILike } from 'typeorm';
import { User } from './entities/user.entity';

@Injectable()
export class UsersService {
  constructor(
    @InjectRepository(User) private repo: Repository<User>,
  ) {}

  // [CREATE] - Yangi foydalanuvchi yaratish
  async create(dto: CreateUserDto): Promise<User> {
    const user = this.repo.create(dto);
    return this.repo.save(user);
  }

  // [READ ALL & PAGINATION] - Sahifalash mantig'i xizmat darajasida
  async findAll(page: number = 1, limit: number = 10, search?: string) {
    // Matematik hisob-kitob aynan Servisda bo'ladi!
    const skip = (page - 1) * limit; 

    const where = search ? { name: ILike(`%${search}%`) } : {};

    // Baza bilan to'g'ridan to'g'ri ishlash
    const [data, total] = await this.repo.findAndCount({
      where,
      take: limit, // qancha tortish
      skip: skip,  // qanchasini o'tkazib yuborish
      order: { id: 'DESC' } 
    });

    // Qaytayotgan javobni formatlash
    return {
      data,
      meta: { total, page, limit, totalPages: Math.ceil(total / limit) }
    };
  }

  // [READ ONE] - Bitta elementni topish
  async findOne(id: number): Promise<User> {
    const user = await this.repo.findOneBy({ id });
    if (!user) throw new NotFoundException('Topilmadi');
    return user;
  }

  // [UPDATE] - Ma'lumotni qisman yangilash
  async update(id: number, dto: UpdateUserDto): Promise<User> {
    // Avval borligini tekshiramiz (findOne o'zida NotFoundException otadi)
    const user = await this.findOne(id);

    // Obyektni yangi kelgan ma'lumotlar bilan boyitamiz
    Object.assign(user, dto);

    // Saqlaymiz va qaytaramiz
    return this.repo.save(user);
  }

  // [DELETE] - Ma'lumotni o'chirish
  async remove(id: number): Promise<void> {
    const result = await this.repo.delete(id);
    if (result.affected === 0) throw new NotFoundException('Topilmadi');
  }
}

import { ConflictException, Injectable, Module, NotFoundException } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, CreateDateColumn, Entity, Like, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class User {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @Column({ unique: true }) email: string
    @Column({ default: "user" }) role: string
    @CreateDateColumn() createdAt: Date
}

type Filter = { page: number; limit: number; search?: string; role?: string }

@Injectable()
class UsersService {
    constructor(@InjectRepository(User) private readonly repo: Repository<User>) {}

    async create(dto: Pick<User, "name" | "email">) {
        if (await this.repo.existsBy({ email: dto.email })) throw new ConflictException("Email band")
        return this.repo.save(dto)
    }

    async findAll({ page, limit, search, role }: Filter) {
        const where = { ...(search && { name: Like(`%${search}%`) }), ...(role && { role }) }
        const [data, total] = await this.repo.findAndCount({ where, order: { id: "ASC" }, skip: (page - 1) * limit, take: limit, select: { id: true, name: true, role: true } })
        return { data, meta: { page, limit, total, totalPages: Math.ceil(total / limit) } }
    }

    async findOne(id: number) {
        const user = await this.repo.findOneBy({ id })
        if (!user) throw new NotFoundException(`Foydalanuvchi #${id} topilmadi`)
        return user
    }

    async update(id: number, dto: Partial<User>) {
        const user = await this.findOne(id)
        return this.repo.save(this.repo.merge(user, dto))
    }

    async remove(id: number) {
        await this.repo.remove(await this.findOne(id))
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [User], synchronize: true }), TypeOrmModule.forFeature([User])], providers: [UsersService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const s = app.get(UsersService)
    for (const [name, email] of [["Ali", "ali@x.uz"], ["Alisher", "alisher@x.uz"], ["Laylo", "laylo@x.uz"], ["Bek", "bek@x.uz"]]) await s.create({ name, email })
    await s.update(4, { role: "admin" })
    console.log(JSON.stringify(await s.findAll({ page: 1, limit: 2 })))
    console.log(JSON.stringify(await s.findAll({ page: 1, limit: 10, search: "Ali" })))
    console.log(JSON.stringify(await s.findAll({ page: 1, limit: 10, role: "admin" })))
    await s.remove(3)
    try { await s.findOne(3) } catch (e: any) { console.log(e.status, e.message) }
    try { await s.create({ name: "Ali 2", email: "ali@x.uz" }) } catch (e: any) { console.log(e.status, e.message) }
    await app.close()
}
