import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { BeforeUpdate, Column, Entity, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class User {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @Column({ default: 0 }) edits: number
    @BeforeUpdate() countEdit() { this.edits++ }
}

@Injectable()
class Demo {
    constructor(@InjectRepository(User) private readonly repo: Repository<User>) {}
    async run() {
        await this.repo.save({ name: "Ali" })
        const u = await this.repo.findOneByOrFail({ id: 1 })
        await this.repo.save(this.repo.merge(u, { name: "Ali (merge)" }))
        console.log("merge+save:", await this.repo.findOneBy({ id: 1 }))
        await this.repo.update(1, { name: "Ali (update)" })
        console.log("update():", await this.repo.findOneBy({ id: 1 }), "← @BeforeUpdate ishlamadi")
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [User], synchronize: true }), TypeOrmModule.forFeature([User])], providers: [Demo] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    await app.get(Demo).run()
    await app.close()
}
main()

import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, MoreThan, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Message { @PrimaryGeneratedColumn() id: number; @Column() text: string }

@Injectable()
class MessagesService {
    constructor(@InjectRepository(Message) private readonly repo: Repository<Message>) {}
    async page(cursor = 0, limit = 3) {
        const items = await this.repo.find({ where: { id: MoreThan(cursor) }, order: { id: "ASC" }, take: limit + 1 })
        const hasMore = items.length > limit
        const data = items.slice(0, limit)
        return { data: data.map(m => m.text), nextCursor: hasMore ? data[data.length - 1].id : null }
    }
}

