import { ArgumentsHost, Catch, ConflictException, Controller, ExceptionFilter, Injectable, Module, Param, Post } from "@nestjs/common"
import { APP_FILTER } from "@nestjs/core"

class DomainError extends Error { constructor(readonly code: "OUT_OF_STOCK" | "NOT_FOUND", message: string) { super(message) } }

@Injectable()
class InventoryService {
    private stock = new Map([["choy", 1]])
    reserve(sku: string) {
        if (!this.stock.has(sku)) throw new DomainError("NOT_FOUND", `${sku} mavjud emas`)
        if (!this.stock.get(sku)) throw new DomainError("OUT_OF_STOCK", `${sku} tugagan`)
        this.stock.set(sku, this.stock.get(sku)! - 1)
        return { reserved: sku }
    }
}

@Catch(DomainError)
class DomainErrorFilter implements ExceptionFilter {
    catch(e: DomainError, host: ArgumentsHost) {
        const status = { NOT_FOUND: 404, OUT_OF_STOCK: 409 }[e.code]
        host.switchToHttp().getResponse().status(status).json({ statusCode: status, code: e.code, message: e.message })
    }
}

@Controller("inventory")
class InventoryController {
    constructor(private readonly s: InventoryService) {}
    @Post(":sku/reserve") reserve(@Param("sku") sku: string) { return this.s.reserve(sku) }
}

@Module({ controllers: [InventoryController], providers: [InventoryService, { provide: APP_FILTER, useClass: DomainErrorFilter }] })
class AppModule {}

