abstract class BaseCrudService<T extends { id: number }> {
    protected constructor(protected readonly repo: Repository<T>, private readonly label: string) {}
    findAll() { return this.repo.find() }
    async findOne(id: number) {
        const e = await this.repo.findOneBy({ id } as FindOptionsWhere<T>)
        if (!e) throw new NotFoundException(`${this.label} #${id} topilmadi`)
        return e
    }
    create(dto: DeepPartial<T>) { return this.repo.save(dto) }
    async remove(id: number) { await this.repo.remove(await this.findOne(id)) }
}

