type Item = { price: number; qty: number }

@Injectable()
class CheckoutService {
    // ✔ har bir qadam alohida, test qilish oson
    subtotal(items: Item[]) { return items.reduce((s, i) => s + i.price * i.qty, 0) }
    discount(subtotal: number, promo?: string) { return promo === "YOZ10" ? Math.round(subtotal * 0.1) : 0 }
    delivery(afterDiscount: number) { return afterDiscount >= 100_000 ? 0 : 15_000 }

    total(items: Item[], promo?: string) {
        const subtotal = this.subtotal(items)
        const discount = this.discount(subtotal, promo)
        const delivery = this.delivery(subtotal - discount)
        return { subtotal, discount, delivery, total: subtotal - discount + delivery }
    }
}

