import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

type Result<T, E extends string> = { ok: true; value: T } | { ok: false; error: E }
const ok = <T>(value: T) => ({ ok: true as const, value })
const fail = <E extends string>(error: E) => ({ ok: false as const, error })

@Injectable()
class CouponService {
    private coupons = new Map([["OSH10", { percent: 10, used: false }], ["ESKI", { percent: 5, used: true }]])

    apply(code: string, total: number): Result<number, "NOT_FOUND" | "ALREADY_USED"> {
        const c = this.coupons.get(code)
        if (!c) return fail("NOT_FOUND")
        if (c.used) return fail("ALREADY_USED")
        return ok(total - Math.round((total * c.percent) / 100))
    }
}

@Module({ providers: [CouponService] }) class AppModule {}

