abstract class Clock { abstract now(): Date }
class FixedClock extends Clock {
    constructor(private current: Date) { super() }
    now() { return this.current }
    advanceDays(d: number) { this.current = new Date(this.current.getTime() + d * 86_400_000) }
}

@Injectable()
class SubscriptionService {
    constructor(@Inject(Clock) private readonly clock: Clock) {}
    private endsAt = new Date("2025-03-31T00:00:00Z")
    status() {
        const days = Math.ceil((this.endsAt.getTime() - this.clock.now().getTime()) / 86_400_000)
        return days > 0 ? `faol, ${days} kun qoldi` : "muddati tugagan"
    }
}

const clock = new FixedClock(new Date("2025-03-25T00:00:00Z"))
