const wait = <T>(ms: number, v: T) => new Promise<T>(r => setTimeout(() => r(v), ms))

@Injectable()
class DashboardService {
    user(id: number) { return wait(50, { id, name: "Ali" }) }
    orders(_: number) { return wait(50, 12) }
    bonus(_: number) { return wait(50, 3400) }

    async sequential(id: number) {
        return { user: await this.user(id), orders: await this.orders(id), bonus: await this.bonus(id) }
    }
    async parallel(id: number) {
        const [user, orders, bonus] = await Promise.all([this.user(id), this.orders(id), this.bonus(id)])
        return { user, orders, bonus }
    }
}

