@Entity() class Article { @PrimaryGeneratedColumn() id: number; @Column() title: string; @Column({ unique: true }) slug: string }

@Injectable()
class ArticlesService {
    constructor(@InjectRepository(Article) private readonly repo: Repository<Article>) {}

    private async uniqueSlug(title: string) {
        const base = title.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "")
        const taken = new Set((await this.repo.find({ where: { slug: Like(`${base}%`) }, select: { slug: true } })).map(a => a.slug))
        if (!taken.has(base)) return base
        let n = 2
        while (taken.has(`${base}-${n}`)) n++
        return `${base}-${n}`
    }

    async create(title: string) { return this.repo.save({ title, slug: await this.uniqueSlug(title) }) }
}

