    async importAll(rows: Omit<Reading, "id">[], chunkSize = 400) {
        let batches = 0
        for (let i = 0; i < rows.length; i += chunkSize) {
            await this.repo.insert(rows.slice(i, i + chunkSize))
            batches++
        }
        return { rows: rows.length, batches, inDb: await this.repo.count() }
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Reading], synchronize: true }), TypeOrmModule.forFeature([Reading])], providers: [ImportService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const rows = Array.from({ length: 1000 }, (_, i) => ({ sensor: `s${i % 4}`, value: i / 10 }))
    console.log(await app.get(ImportService).importAll(rows))
    await app.close()
}
main()

import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

interface Profile { name: string; city: string; phone: string }
type Patch = { [K in keyof Profile]?: Profile[K] }

@Injectable()
class ProfileService {
    naive(p: Profile, patch: Patch) { return Object.assign({ ...p }, patch) }
    safe(p: Profile, patch: Patch) {
        const defined = Object.fromEntries(Object.entries(patch).filter(([, v]) => v !== undefined))
        return { ...p, ...defined }
    }
}

@Module({ providers: [ProfileService] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const s = app.get(ProfileService)
    const profile = { name: "Ali", city: "Toshkent", phone: "+998901234567" }
    const patch: Patch = { city: "Xiva", phone: undefined } // formadan bo'sh maydon keldi
    console.log("naive:", s.naive(profile, patch))
    console.log("safe: ", s.safe(profile, patch))
    await app.close()
}
