type Status = "new" | "paid" | "shipped" | "cancelled"
const TRANSITIONS: Record<Status, Status[]> = {
    new: ["paid", "cancelled"],
    paid: ["shipped", "cancelled"],
    shipped: [],
    cancelled: [],
}

@Injectable()
class OrderStatusService {
    private status: Status = "new"
    move(to: Status) {
        if (!TRANSITIONS[this.status].includes(to)) throw new BadRequestException(`${this.status} → ${to} mumkin emas`)
        this.status = to
        return this.status
    }
}

