    const s = app.get(OrderStatusService)
    for (const to of ["paid", "new", "shipped", "cancelled"] as Status[]) {
        try { console.log("✓", s.move(to)) } catch (e) { console.log("✗", (e as Error).message) }
    }
    await app.close()
}
