@Entity() class Category { @PrimaryGeneratedColumn() id: number; @Column() name: string }
@Entity() class Product {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @ManyToOne(() => Category, { nullable: false }) category: Relation<Category>
