import { Body, Controller, Delete, Get, HttpCode, Injectable, Module, NotFoundException, Param, ParseIntPipe, Patch, Post, Query, ValidationPipe } from "@nestjs/common"
import { PartialType } from "@nestjs/mapped-types"
import { Type } from "class-transformer"
import { IsEmail, IsInt, IsOptional, IsString, Max, Min, MinLength } from "class-validator"

class CreateUserDto { @IsString() @MinLength(2) name: string; @IsEmail() email: string }
class UpdateUserDto extends PartialType(CreateUserDto) {}
class QueryDto {
    @IsOptional() @Type(() => Number) @IsInt() @Min(1) page: number = 1
    @IsOptional() @Type(() => Number) @IsInt() @Min(1) @Max(50) limit: number = 2
}

type User = CreateUserDto & { id: number }

@Injectable()
class UsersService {
    private users: User[] = []
    private next = 1
    create(dto: CreateUserDto) { const u = { id: this.next++, ...dto }; this.users.push(u); return u }
    findAll({ page, limit }: QueryDto) {
        return { data: this.users.slice((page - 1) * limit, page * limit), meta: { page, limit, total: this.users.length } }
    }
    findOne(id: number) { const u = this.users.find(x => x.id === id); if (!u) throw new NotFoundException(`#${id} topilmadi`); return u }
    update(id: number, dto: UpdateUserDto) { return Object.assign(this.findOne(id), dto) }
    remove(id: number) { this.findOne(id); this.users = this.users.filter(u => u.id !== id) }
}

@Controller("users")
class UsersController {
    constructor(private readonly users: UsersService) {}
    @Post() create(@Body() dto: CreateUserDto) { return this.users.create(dto) }
    @Get() findAll(@Query() q: QueryDto) { return this.users.findAll(q) }
    @Get(":id") findOne(@Param("id", ParseIntPipe) id: number) { return this.users.findOne(id) }
    @Patch(":id") update(@Param("id", ParseIntPipe) id: number, @Body() dto: UpdateUserDto) { return this.users.update(id, dto) }
    @Delete(":id") @HttpCode(204) remove(@Param("id", ParseIntPipe) id: number) { this.users.remove(id) }
}

@Module({ controllers: [UsersController], providers: [UsersService] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule, app => app.useGlobalPipes(new ValidationPipe({ transform: true, whitelist: true })))
    await http.post("/users", { name: "Ali", email: "ali@x.uz" })
    await http.post("/users", { name: "Laylo", email: "laylo@x.uz" })
    await http.post("/users", { name: "Bek", email: "bek@x.uz" })
    await http.get("/users?page=2")
    await http.patch("/users/2", { name: "Laylo Karimova" })
    await http.delete("/users/1")
    await http.get("/users/1")
    await http.get("/users/abc")
    await http.close()
}
main()

