const products: { id: number; name: string; price: number }[] = []

@Controller("products")
class ProductsController {
    @Post("bulk")
    @HttpCode(200)
    bulk(@Body() items: { name?: string; price?: number }[]) {
        const results = items.map((it, index) => {
            if (!it.name) return { index, status: 400, error: "name majburiy" }
            if (!(Number(it.price) > 0)) return { index, status: 400, error: "price musbat bo'lsin" }
            const p = { id: products.length + 1, name: it.name, price: it.price! }
            products.push(p)
            return { index, status: 201, id: p.id }
        })
        return { created: results.filter(r => r.status === 201).length, failed: results.filter(r => r.status !== 201).length, results }
    }
}

