import {
    Body, Controller, Delete, Get, HttpCode, Injectable, Module,
    NotFoundException, Param, ParseIntPipe, Patch, Post, Put,
} from "@nestjs/common"

type Product = { id: number; name: string; price: number }
type CreateProduct = Omit<Product, "id">

@Injectable()
class ProductsService {
    private products: Product[] = []
    private nextId = 1

    findAll() {
        return this.products
    }

    findOne(id: number) {
        const product = this.products.find(p => p.id === id)
        if (!product) throw new NotFoundException(`Mahsulot #${id} topilmadi`)
        return product
    }

    create(data: CreateProduct) {
        const product = { id: this.nextId++, ...data }
        this.products.push(product)
        return product
    }

    update(id: number, data: Partial<CreateProduct>) {
        const product = this.findOne(id)
        Object.assign(product, data)
        return product
    }

    replace(id: number, data: CreateProduct) {
        const index = this.products.findIndex(p => p.id === id)
        if (index === -1) throw new NotFoundException(`Mahsulot #${id} topilmadi`)
        this.products[index] = { id, ...data }
        return this.products[index]
    }

    remove(id: number) {
        this.findOne(id)
        this.products = this.products.filter(p => p.id !== id)
    }
}

@Controller("products")
class ProductsController {
    constructor(private readonly service: ProductsService) {}

    @Get() findAll() { return this.service.findAll() }
    @Get(":id") findOne(@Param("id", ParseIntPipe) id: number) { return this.service.findOne(id) }
    @Post() create(@Body() body: CreateProduct) { return this.service.create(body) }
    @Patch(":id") update(@Param("id", ParseIntPipe) id: number, @Body() body: Partial<CreateProduct>) { return this.service.update(id, body) }
    @Put(":id") replace(@Param("id", ParseIntPipe) id: number, @Body() body: CreateProduct) { return this.service.replace(id, body) }
    @Delete(":id") @HttpCode(204) remove(@Param("id", ParseIntPipe) id: number) { this.service.remove(id) }
}

@Module({ controllers: [ProductsController], providers: [ProductsService] })
class AppModule {}

// ─── Sinov ───
async function main() {
    const http = await testApp(AppModule)
    await http.post("/products", { name: "Noutbuk", price: 9_000_000 })
    await http.post("/products", { name: "Telefon", price: 4_500_000 })
    await http.get("/products")
    await http.get("/products/1")
    await http.patch("/products/1", { price: 8_500_000 })
    await http.put("/products/2", { name: "iPhone 16", price: 14_000_000 })
    await http.delete("/products/1")
    await http.get("/products/1")
