import { Body, Controller, Get, Injectable, Module, NotFoundException, Param, ParseIntPipe, Post } from "@nestjs/common"

abstract class InMemoryCrudService<T extends { id: number }> {
    protected items: T[] = []
    private nextId = 1

    findAll(): T[] { return this.items }

    findOne(id: number): T {
        const item = this.items.find(i => i.id === id)
        if (!item) throw new NotFoundException(`${this.constructor.name}: #${id} topilmadi`)
        return item
    }

    create(data: Omit<T, "id">): T {
        const item = { id: this.nextId++, ...data } as T
        this.items.push(item)
        return item
    }
}

