import { Controller, Delete, Get, Module, NotFoundException, Param, ParseIntPipe, Post } from "@nestjs/common"

const items = [{ id: 1, name: "Non" }, { id: 2, name: "Sut" }, { id: 3, name: "Tuxum" }]
const trash: { item: (typeof items)[number]; index: number }[] = []

@Controller("list")
class ListController {
    @Get() all() { return items.map(i => i.name) }
    @Delete(":id") remove(@Param("id", ParseIntPipe) id: number) {
        const index = items.findIndex(i => i.id === id)
        if (index < 0) throw new NotFoundException()
        trash.push({ item: items.splice(index, 1)[0], index })
        return items.map(i => i.name)
    }
    @Post("undo") undo() {
        const last = trash.pop()
        if (!last) throw new NotFoundException("Qaytaradigan narsa yo'q")
        items.splice(last.index, 0, last.item)
        return items.map(i => i.name)
    }
}

@Module({ controllers: [ListController] }) class AppModule {}

