import { Body, Controller, Module, Patch } from "@nestjs/common"

type Obj = Record<string, unknown>
const isObj = (v: unknown): v is Obj => typeof v === "object" && v !== null && !Array.isArray(v)
function deepMerge(target: Obj, patch: Obj): Obj {
    const out: Obj = { ...target }
    for (const [k, v] of Object.entries(patch)) out[k] = isObj(v) && isObj(out[k]) ? deepMerge(out[k] as Obj, v) : v
    return out
}

let settings: Obj = { theme: "light", notifications: { email: true, sms: true, push: false } }

@Controller("settings")
class SettingsController {
    @Patch("shallow") shallow(@Body() patch: Obj) { return { ...settings, ...patch } }
    @Patch("deep") deep(@Body() patch: Obj) { settings = deepMerge(settings, patch); return settings }
}

@Module({ controllers: [SettingsController] }) class AppModule {}

