import { BadRequestException, Body, Controller, Module, Patch } from "@nestjs/common"

type Op = { op: "replace" | "add" | "remove"; path: string; value?: unknown }
const recipe: Record<string, unknown> = { name: "Osh", time: 90, tags: ["milliy"] }

function apply(doc: Record<string, unknown>, ops: Op[]) {
    const out = structuredClone(doc)
    for (const { op, path, value } of ops) {
        const [key, index] = path.slice(1).split("/")
        if (op === "remove") delete out[key]
        else if (op === "add" && index === "-") (out[key] as unknown[]).push(value)
        else if (op === "replace" || op === "add") out[key] = value
        else throw new BadRequestException(`Qo'llab-quvvatlanmaydi: ${op} ${path}`)
    }
    return out
}

@Controller("recipes")
class RecipesController {
    @Patch("1") patch(@Body() ops: Op[]) { return apply(recipe, ops) }
}

@Module({ controllers: [RecipesController] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.patch("/recipes/1", [
        { op: "replace", path: "/time", value: 75 },
        { op: "add", path: "/tags/-", value: "bayram" },
        { op: "remove", path: "/name" },
    ])
    await http.close()
}
