import { Body, Controller, Delete, Get, HttpCode, Injectable, Module, NotFoundException, Param, ParseIntPipe, Patch, Post } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, PrimaryGeneratedColumn, Repository } from "typeorm"

// ── entity ──
@Entity("products")
class Product {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @Column("int") price: number
    @Column({ default: 0 }) stock: number
}

// ── servis ──
@Injectable()
class ProductsService {
    constructor(@InjectRepository(Product) private readonly repo: Repository<Product>) {}

    findAll() {
        return this.repo.find({ order: { id: "ASC" } })
    }

    async findOne(id: number) {
        const product = await this.repo.findOneBy({ id })
        if (!product) throw new NotFoundException(`Mahsulot #${id} topilmadi`)
        return product
    }

    create(data: Partial<Product>) {
        return this.repo.save(this.repo.create(data))
    }

    async update(id: number, data: Partial<Product>) {
        const product = await this.repo.preload({ id, ...data })   // topib, ustiga yozadi
        if (!product) throw new NotFoundException(`Mahsulot #${id} topilmadi`)
        return this.repo.save(product)
    }

    async remove(id: number) {
        const result = await this.repo.delete(id)
        if (!result.affected) throw new NotFoundException(`Mahsulot #${id} topilmadi`)
    }
}

// ── controller ──
@Controller("products")
class ProductsController {
    constructor(private readonly service: ProductsService) {}
    @Get() findAll() { return this.service.findAll() }
    @Get(":id") findOne(@Param("id", ParseIntPipe) id: number) { return this.service.findOne(id) }
    @Post() create(@Body() body: Partial<Product>) { return this.service.create(body) }
    @Patch(":id") update(@Param("id", ParseIntPipe) id: number, @Body() body: Partial<Product>) { return this.service.update(id, body) }
    @Delete(":id") @HttpCode(204) remove(@Param("id", ParseIntPipe) id: number) { return this.service.remove(id) }
}

// ── modul ──
@Module({
    imports: [
        // Misolda xotiradagi SQLite. Loyihada: { type: "postgres", url: process.env.DATABASE_URL, ... }
        TypeOrmModule.forRoot({ type: "sqljs", entities: [Product], synchronize: true }),
        TypeOrmModule.forFeature([Product]),
    ],
    controllers: [ProductsController],
    providers: [ProductsService],
})
class AppModule {}

