    @Column() owner: string
    @Column("int") balance: number
}

@Injectable()
class DemoService {
    constructor(@InjectRepository(Account) private repo: Repository<Account>) {}

    async run() {
        const log: string[] = []
        const acc = await this.repo.save({ owner: "Ali", balance: 100 })
        log.push(`save (yangi): id=${acc.id}`)

        acc.balance = 150
        await this.repo.save(acc)
        log.push(`save (mavjud): UPDATE bo'ldi, balans=${(await this.repo.findOneBy({ id: 1 }))!.balance}`)

        const res = await this.repo.update({ id: 1 }, { balance: 200 })
        log.push(`update: affected=${res.affected} (entity qaytarmaydi, hook'lar ishlamaydi)`)

        const missing = await this.repo.update({ id: 99 }, { balance: 1 })
        log.push(`update (yo'q id): affected=${missing.affected} — xato bermaydi!`)

        const preloaded = await this.repo.preload({ id: 1, owner: "Ali K." })
        log.push(`preload: ${JSON.stringify(preloaded)} (hali saqlanmagan)`)

        const none = await this.repo.preload({ id: 99, owner: "X" })
        log.push(`preload (yo'q id): ${none}`)
        return log
    }
}

