import { Body, Controller, Injectable, Module, Post } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Order { @PrimaryGeneratedColumn() id: number; @Column("int") total: number }
@Entity() class Stock { @PrimaryGeneratedColumn() id: number; @Column() sku: string; @Column("int") qty: number }

@Injectable()
class OrdersService {
    constructor(private readonly ds: DataSource, @InjectRepository(Stock) private readonly stock: Repository<Stock>) {}
    seed() { return this.stock.save({ sku: "A1", qty: 5 }) }
    create(sku: string, qty: number, total: number) {
        return this.ds.transaction(async em => {
            const item = await em.findOneByOrFail(Stock, { sku })
            if (item.qty < qty) throw new Error(`Omborda faqat ${item.qty} ta bor`)
            await em.decrement(Stock, { sku }, "qty", qty)
            return em.save(Order, { total })
        })
    }
