import { Inject, Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, MoreThan, PrimaryGeneratedColumn } from "typeorm"

@Entity() class Product { @PrimaryGeneratedColumn() id: number; @Column() name: string; @Column() stock: number }

const PRODUCTS_REPO = "PRODUCTS_REPO"
const productsRepoFactory = (ds: DataSource) =>
    ds.getRepository(Product).extend({
        inStock() { return this.findBy({ stock: MoreThan(0) }) },
        findByName(name: string) { return this.findOneBy({ name }) },
    })
type ProductsRepo = ReturnType<typeof productsRepoFactory>

@Injectable()
class ProductsService {
    constructor(@Inject(PRODUCTS_REPO) private readonly repo: ProductsRepo) {}
    async summary() { return { inStock: (await this.repo.inStock()).map(p => p.name), choy: await this.repo.findByName("Choy") } }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Product], synchronize: true })],
    providers: [ProductsService, { provide: PRODUCTS_REPO, useFactory: productsRepoFactory, inject: [DataSource] }],
})
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    await app.get(DataSource).getRepository(Product).save([{ name: "Non", stock: 5 }, { name: "Choy", stock: 0 }, { name: "Sut", stock: 2 }])
    console.log(await app.get(ProductsService).summary())
    await app.close()
}
main()

