@Injectable()
class OrdersService {
    constructor(
        @InjectRepository(Order) private readonly orders: Repository<Order>,
        @InjectRepository(AuditLog, "audit") private readonly audit: Repository<AuditLog>,
    ) {}
    async create(total: number) {
        const o = await this.orders.save({ total })
        await this.audit.save({ message: `buyurtma #${o.id} yaratildi (${total})` })
        return { orders: await this.orders.count(), auditLogs: await this.audit.find() }
    }
}

