import { Body, Controller, Module, Post, ValidationPipe } from "@nestjs/common"
import { IsDateString, Validate, ValidationArguments, ValidatorConstraint, ValidatorConstraintInterface } from "class-validator"

@ValidatorConstraint({ name: "isAfter" })
class IsAfter implements ValidatorConstraintInterface {
    validate(value: string, args: ValidationArguments) {
        const [field] = args.constraints
        return new Date(value) > new Date((args.object as Record<string, string>)[field])
    }
    defaultMessage(args: ValidationArguments) { return `${args.property} ${args.constraints[0]} dan keyin bo'lishi kerak` }
}

