import { ArgumentsHost, BadRequestException, Body, Catch, Controller, ExceptionFilter, Module, Post, ValidationPipe } from "@nestjs/common"
import { IsEmail, IsInt, Min } from "class-validator"

@Catch(BadRequestException)
class ValidationFilter implements ExceptionFilter {
    catch(e: BadRequestException, host: ArgumentsHost) {
        const body = e.getResponse() as { message: string[] | string }
        const messages = ([] as string[]).concat(body.message)
        const errors = messages.reduce<Record<string, string[]>>((acc, m) => {
            const field = m.split(" ")[0]
            return { ...acc, [field]: [...(acc[field] ?? []), m] }
        }, {})
        host.switchToHttp().getResponse().status(422).json({ statusCode: 422, errors })
    }
}

