import { Body, Controller, Injectable, Module, Post, ValidationPipe } from "@nestjs/common"
import { getRepositoryToken, InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { IsString, registerDecorator, useContainer, ValidatorConstraint, ValidatorConstraintInterface } from "class-validator"
import { Column, Entity, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Category { @PrimaryGeneratedColumn() id: number; @Column({ unique: true }) name: string }

@ValidatorConstraint({ async: true }) @Injectable()
class UniqueCategoryName implements ValidatorConstraintInterface {
    constructor(@InjectRepository(Category) private readonly repo: Repository<Category>) {}
    async validate(name: string) { return !(await this.repo.existsBy({ name })) }
    defaultMessage() { return "Bunday nomli kategoriya allaqachon bor" }
}
const IsUniqueName = () => (o: object, prop: string) => registerDecorator({ target: o.constructor, propertyName: prop, validator: UniqueCategoryName })

class CreateCategoryDto { @IsString() @IsUniqueName() name: string }

@Controller("categories")
class CategoriesController {
    constructor(@InjectRepository(Category) private readonly repo: Repository<Category>) {}
    @Post() create(@Body() dto: CreateCategoryDto) { return this.repo.save(dto) }
}
@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Category], synchronize: true }), TypeOrmModule.forFeature([Category])], controllers: [CategoriesController], providers: [UniqueCategoryName] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule, app => {
        useContainer(app.select(AppModule), { fallbackOnErrors: true })   // validator'ga DI
        app.useGlobalPipes(new ValidationPipe())
    })
    await http.app.get<Repository<Category>>(getRepositoryToken(Category)).save({ name: "Ichimliklar" })
    await http.post("/categories", { name: "Shirinliklar" })
    await http.post("/categories", { name: "Ichimliklar" })
    await http.close()
}
main()

