import { Body, Controller, Module, Post, ValidationPipe } from "@nestjs/common"
import { registerDecorator, ValidationOptions } from "class-validator"

const TODAY = new Date("2025-06-01") // misolda aniq natija uchun; amalda new Date()

function MinAge(years: number, options?: ValidationOptions) {
    return (target: object, propertyName: string) =>
        registerDecorator({
            name: "minAge",
            target: target.constructor,
            propertyName,
            constraints: [years],
            options: { message: `Kamida ${years} yosh bo'lishi kerak`, ...options },
            validator: {
                validate(value: unknown) {
                    const birth = new Date(String(value))
                    if (isNaN(birth.getTime())) return false
                    const limit = new Date(birth)
                    limit.setFullYear(birth.getFullYear() + years)
                    return limit <= TODAY
                },
            },
        })
}

class RegisterDto { @MinAge(18) birthDate: string }

