import { Controller, Get, Injectable, Module, Query, ValidationPipe } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Type } from "class-transformer"
import { IsIn, IsInt, IsOptional, IsString, Max, Min } from "class-validator"
import { Column, Entity, FindOptionsWhere, Like, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Product {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @Column() category: string
    @Column("int") price: number
}

class ProductQueryDto {
    @IsOptional() @Type(() => Number) @IsInt() @Min(1) page = 1
    @IsOptional() @Type(() => Number) @IsInt() @Min(1) @Max(50) limit = 3
    @IsOptional() @IsString() search?: string
    @IsOptional() @IsString() category?: string
    @IsOptional() @IsIn(["name", "price", "id"]) sort: "name" | "price" | "id" = "id"    // whitelist!
    @IsOptional() @IsIn(["ASC", "DESC"]) order: "ASC" | "DESC" = "ASC"
}

@Injectable() class ProductsService {
    constructor(@InjectRepository(Product) private repo: Repository<Product>) {}

    async findAll(q: ProductQueryDto) {
        const where: FindOptionsWhere<Product> = {}
        if (q.search) where.name = Like(`%${q.search}%`)      // Postgres'da: ILike
        if (q.category) where.category = q.category

        const [data, total] = await this.repo.findAndCount({
            where,
            order: { [q.sort]: q.order },
            skip: (q.page - 1) * q.limit,
            take: q.limit,
        })
        return { data: data.map(p => `${p.name} (${p.price})`), meta: { page: q.page, limit: q.limit, total, totalPages: Math.ceil(total / q.limit) } }
    }

    seed() {
        return this.repo.save([
            { name: "Noutbuk Acer", category: "tech", price: 7000 }, { name: "Noutbuk Asus", category: "tech", price: 8500 },
            { name: "Telefon", category: "tech", price: 4000 }, { name: "Ko'ylak", category: "clothes", price: 300 },
            { name: "Shim", category: "clothes", price: 450 }, { name: "Planshet", category: "tech", price: 3500 },
            { name: "Kurtka", category: "clothes", price: 900 },
        ])
    }
}

@Controller("products") class ProductsController {
    constructor(private s: ProductsService) {}
    @Get() list(@Query() q: ProductQueryDto) { return this.s.findAll(q) }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Product], synchronize: true }), TypeOrmModule.forFeature([Product])],
    controllers: [ProductsController], providers: [ProductsService],
})
class AppModule {}

async function main() {
    const http = await testApp(AppModule, app => app.useGlobalPipes(new ValidationPipe({ transform: true })))
    await http.app.get(ProductsService).seed()
    await http.get("/products")
    await http.get("/products?page=3")
    await http.get("/products?search=noutbuk")
    await http.get("/products?category=clothes&sort=price&order=DESC")
    await http.get("/products?sort=password")
    await http.close()
}
main()

