import { Controller, Get, Injectable, Module, Query } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Between, Column, Entity, FindOptionsWhere, LessThanOrEqual, MoreThanOrEqual, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Flat {
    @PrimaryGeneratedColumn() id: number
    @Column() district: string
    @Column("int") rooms: number
    @Column("int") price: number
}

@Injectable() class FlatsService {
    constructor(@InjectRepository(Flat) private repo: Repository<Flat>) {}

    seed() {
        return this.repo.save([
            { district: "Chilonzor", rooms: 2, price: 45000 }, { district: "Yunusobod", rooms: 3, price: 78000 },
            { district: "Chilonzor", rooms: 1, price: 30000 }, { district: "Mirzo Ulug'bek", rooms: 4, price: 120000 },
            { district: "Yunusobod", rooms: 2, price: 52000 },
        ])
    }

    search(min?: number, max?: number, rooms?: number) {
        // Diqqat: where ichiga undefined qiymat bermang — faqat berilgan filtrlarni qo'shing
        const where: FindOptionsWhere<Flat> = {}
        if (min !== undefined && max !== undefined) where.price = Between(min, max)
        else if (min !== undefined) where.price = MoreThanOrEqual(min)
        else if (max !== undefined) where.price = LessThanOrEqual(max)
        if (rooms !== undefined) where.rooms = rooms
        return this.repo.find({ where, order: { price: "ASC" } })
    }
}

@Controller("flats") class FlatsController {
    constructor(private s: FlatsService) {}
    @Get()
    async search(@Query("min") min?: string, @Query("max") max?: string, @Query("rooms") rooms?: string) {
        const flats = await this.s.search(min ? +min : undefined, max ? +max : undefined, rooms ? +rooms : undefined)
        return flats.map(f => `${f.district}, ${f.rooms} xona — $${f.price}`)
    }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Flat], synchronize: true }), TypeOrmModule.forFeature([Flat])],
    controllers: [FlatsController], providers: [FlatsService],
})
