import { Controller, Get, Injectable, Module, Query } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, LessThan, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Post {
    @PrimaryGeneratedColumn() id: number
    @Column() title: string
}

@Injectable() class FeedService {
    constructor(@InjectRepository(Post) private repo: Repository<Post>) {}

    seed() {
        return this.repo.save(Array.from({ length: 7 }, (_, i) => ({ title: `Post ${i + 1}` })))
    }

    async feed(cursor?: number, limit = 3) {
        const posts = await this.repo.find({
            where: cursor ? { id: LessThan(cursor) } : {},
            order: { id: "DESC" },                 // eng yangisi birinchi
            take: limit + 1,                       // keyingi sahifa borligini bilish uchun +1
        })
        const hasMore = posts.length > limit
        const items = posts.slice(0, limit)
        return { items: items.map(p => p.title), nextCursor: hasMore ? items[items.length - 1].id : null }
    }
}

@Controller("feed") class FeedController {
    constructor(private s: FeedService) {}
    @Get() feed(@Query("cursor") cursor?: string) { return this.s.feed(cursor ? Number(cursor) : undefined) }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Post], synchronize: true }), TypeOrmModule.forFeature([Post])],
    controllers: [FeedController], providers: [FeedService],
})
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.app.get(FeedService).seed()
    let res = await http.get("/feed")
    while (res.data.nextCursor) {
        res = await http.get(`/feed?cursor=${res.data.nextCursor}`)
    }
    await http.close()
}
