class PaginationInterceptor implements NestInterceptor {
    intercept(ctx: ExecutionContext, next: CallHandler) {
        const q = ctx.switchToHttp().getRequest().query
        const page = Number(q.page ?? 1), limit = Number(q.limit ?? 10)
        return next.handle().pipe(map(([data, total]: [unknown[], number]) => ({
            data,
            meta: { page, limit, total, pages: Math.ceil(total / limit) },
        })))
    }
}

const ALL = Array.from({ length: 14 }, (_, i) => `element-${i + 1}`)

@Controller("items")
@UseInterceptors(PaginationInterceptor)
class ItemsController {
    @Get() list(@Query("page") page = "1", @Query("limit") limit = "5"): [string[], number] {
        const p = +page, l = +limit
        return [ALL.slice((p - 1) * l, p * l), ALL.length]
    }
}

