type PageQuery = { page?: number; limit?: number }
type Paginated<T> = { data: T[]; meta: { page: number; limit: number; total: number; pages: number } }

async function paginate<T extends ObjectLiteral>(repo: Repository<T>, query: PageQuery, options: FindManyOptions<T> = {}): Promise<Paginated<T>> {
    const page = Math.max(1, query.page ?? 1)
    const limit = Math.min(100, Math.max(1, query.limit ?? 10))
    const [data, total] = await repo.findAndCount({ ...options, skip: (page - 1) * limit, take: limit })
    return { data, meta: { page, limit, total, pages: Math.ceil(total / limit) } }
}

