import { Controller, Get, Injectable, Module, Query } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Brackets, Column, Entity, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Event_ { @PrimaryGeneratedColumn() id: number; @Column() createdAt: string; @Column() name: string }

@Injectable()
class EventsService {
    constructor(@InjectRepository(Event_) private readonly repo: Repository<Event_>) {}
    seed() {
        return this.repo.save([
            { createdAt: "2026-09-01", name: "a" }, { createdAt: "2026-09-01", name: "b" }, { createdAt: "2026-09-02", name: "c" },
            { createdAt: "2026-09-02", name: "d" }, { createdAt: "2026-09-03", name: "e" },
        ])
    }
    async page(after?: string, limit = 2) {
        const qb = this.repo.createQueryBuilder("e").orderBy("e.createdAt", "ASC").addOrderBy("e.id", "ASC").take(limit + 1)
        if (after) {
            const [at, id] = after.split("_")
            qb.where(new Brackets(w => w.where("e.createdAt > :at", { at }).orWhere("e.createdAt = :at AND e.id > :id", { at, id: +id })))
        }
        const rows = await qb.getMany()
        const data = rows.slice(0, limit)
        const last = data[data.length - 1]
        return { data: data.map(e => e.name), next: rows.length > limit ? `${last.createdAt}_${last.id}` : null }
    }
}

@Controller("events") class EventsController { constructor(private readonly s: EventsService) {} @Get() list(@Query("after") after?: string) { return this.s.page(after) } }
