function pageNumbers(current: number, total: number, around = 1): (number | "…")[] {
    const pages = new Set([1, total])
    for (let p = current - around; p <= current + around; p++) if (p >= 1 && p <= total) pages.add(p)
    const sorted = [...pages].sort((a, b) => a - b)
    const out: (number | "…")[] = []
    sorted.forEach((p, i) => {
        if (i > 0 && p - sorted[i - 1] > 1) out.push("…")
        out.push(p)
    })
    return out
}

for (const [current, total] of [[1, 20], [5, 20], [19, 20], [2, 3]]) {
    console.log(`${current}/${total}:`, pageNumbers(current, total).join(" "))
