import { BadRequestException, Controller, Get, Module, Query } from "@nestjs/common"
import { createHmac, timingSafeEqual } from "node:crypto"

const SECRET = "cursor-secret"
const sign = (payload: string) => createHmac("sha256", SECRET).update(payload).digest("base64url").slice(0, 16)
const encode = (id: number) => { const p = Buffer.from(String(id)).toString("base64url"); return `${p}.${sign(p)}` }
function decode(cursor: string) {
    const [p, sig] = cursor.split(".")
    const expected = sign(p ?? "")
    if (!sig || sig.length !== expected.length || !timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) throw new BadRequestException("Cursor imzosi noto'g'ri")
    return Number(Buffer.from(p, "base64url").toString())
}

const ids = Array.from({ length: 10 }, (_, i) => i + 1)

@Controller("items")
class ItemsController {
    @Get() list(@Query("cursor") cursor?: string) {
        const after = cursor ? decode(cursor) : 0
        const page = ids.filter(id => id > after).slice(0, 3)
        return { page, next: encode(page[page.length - 1]) }
    }
}

