import { Controller, Get, Module, ParseIntPipe, Query } from "@nestjs/common"

const ids = Array.from({ length: 10 }, (_, i) => i + 1)

@Controller("items")
class ItemsController {
    @Get()
    list(@Query("after", new ParseIntPipe({ optional: true })) after?: number, @Query("before", new ParseIntPipe({ optional: true })) before?: number) {
        const size = 3
        let page: number[]
        if (before !== undefined) page = ids.filter(id => id < before).slice(-size)
        else page = ids.filter(id => id > (after ?? 0)).slice(0, size)
        return {
            page,
            prev: page[0] > ids[0] ? page[0] : null,
            next: page[page.length - 1] < ids[ids.length - 1] ? page[page.length - 1] : null,
        }
    }
}

