import { getRepositoryToken, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Product { @PrimaryGeneratedColumn() id: number; @Column() name: string; @Column() price: number }

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Product], synchronize: true }), TypeOrmModule.forFeature([Product])] })
class AppModule {}

async function page(repo: Repository<Product>, after?: { price: number; id: number }) {
    const qb = repo.createQueryBuilder("p").orderBy("p.price", "DESC").addOrderBy("p.id", "DESC").take(2)
    if (after) qb.where("(p.price < :price OR (p.price = :price AND p.id < :id))", after)
    return qb.getMany()
}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const repo = app.get<Repository<Product>>(getRepositoryToken(Product))
    await repo.save([{ name: "A", price: 5000 }, { name: "B", price: 9000 }, { name: "C", price: 5000 }, { name: "D", price: 9000 }, { name: "E", price: 1000 }])
    let cursor: { price: number; id: number } | undefined
    for (let n = 1; n <= 3; n++) {
        const items = await page(repo, cursor)
        console.log(`${n}-sahifa:`, items.map(p => `${p.name}(${p.price})`).join(", "))
        const last = items[items.length - 1]
        cursor = last && { price: last.price, id: last.id }
    }
    await app.close()
}
main()

