import { Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { getRepositoryToken, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, MoreThan, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Customer { @PrimaryGeneratedColumn() id: number; @Column() name: string }

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Customer], synchronize: true }), TypeOrmModule.forFeature([Customer])] })
class AppModule {}

async function* allCustomers(repo: Repository<Customer>, batch = 40) {
    let lastId = 0
    while (true) {
        const rows = await repo.find({ where: { id: MoreThan(lastId) }, order: { id: "ASC" }, take: batch })
        if (!rows.length) return
        yield rows
        lastId = rows[rows.length - 1].id
    }
}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const repo = app.get<Repository<Customer>>(getRepositoryToken(Customer))
    await repo.insert(Array.from({ length: 100 }, (_, i) => ({ name: `mijoz-${i + 1}` })))
    let total = 0, batches = 0
    for await (const rows of allCustomers(repo)) { batches++; total += rows.length }
    console.log(`${batches} ta paket, jami ${total} ta mijoz`)
    await app.close()
}
main()

