import { BadRequestException, Controller, Get, Module, Query } from "@nestjs/common"

const products = [
    { name: "Choy", price: 12000 }, { name: "Asal", price: 85000 }, { name: "Non", price: 4000 },
    { name: "Bodom", price: 85000 }, { name: "Tuz", price: 4000 },
]
const SORTABLE = ["name", "price"] as const
type Key = (typeof SORTABLE)[number]

function parseSort(sort: string): [Key, 1 | -1][] {
    return sort.split(",").map(part => {
        const dir = part.startsWith("-") ? -1 : 1
        const key = part.replace(/^[-+]/, "") as Key
        if (!SORTABLE.includes(key)) throw new BadRequestException(`Saralab bo'lmaydi: ${key}`)
        return [key, dir]
    })
}

@Controller("products")
class ProductsController {
    @Get() list(@Query("sort") sort = "name") {
        const rules = parseSort(sort)
        return [...products].sort((a, b) => {
            for (const [k, d] of rules) if (a[k] !== b[k]) return (a[k] < b[k] ? -1 : 1) * d
            return 0
        }).map(p => `${p.name}:${p.price}`)
    }
}

@Module({ controllers: [ProductsController] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/products?sort=-price,name")
    await http.get("/products?sort=password")
    await http.close()
}
main()

import { Controller, Get, Module, Query } from "@nestjs/common"

const ids = Array.from({ length: 30 }, (_, i) => i + 1)

function toWindow(q: Record<string, string>) {
    if (q.offset !== undefined || q.limit !== undefined) return { offset: Number(q.offset ?? 0), limit: Number(q.limit ?? 10) }
    const page = Number(q.page ?? 1), size = Number(q.size ?? 10)
    return { offset: (page - 1) * size, limit: size }
}

@Controller("items")
class ItemsController {
    @Get() list(@Query() q: Record<string, string>) {
        const { offset, limit } = toWindow(q)
        return { offset, limit, ids: ids.slice(offset, offset + limit) }
    }
}

