async function cappedCount(repo: Repository<LogRow>, level: string, cap = 1000) {
    // cap+1 ta qatordan ortig'ini sanamaymiz
    const [{ n }] = await repo.query("SELECT COUNT(*) AS n FROM (SELECT 1 FROM log_row WHERE level = ? LIMIT ?)", [level, cap + 1])
    return n > cap ? `${cap}+` : String(n)
}

