import { BadRequestException, Controller, Get, Module, Query } from "@nestjs/common"

let NOW = Date.parse("2025-05-01T10:00:00Z") // misolda boshqariladigan soat
const TTL_MS = 15 * 60_000
const encode = (id: number) => Buffer.from(JSON.stringify({ id, t: NOW })).toString("base64url")
function decode(c: string) {
    const { id, t } = JSON.parse(Buffer.from(c, "base64url").toString())
    if (NOW - t > TTL_MS) throw new BadRequestException("Cursor eskirgan — ro'yxatni boshidan yuklang")
    return id as number
}

@Controller("items")
class ItemsController {
    @Get() list(@Query("cursor") cursor?: string) {
        const after = cursor ? decode(cursor) : 0
        const page = [after + 1, after + 2]
        return { page, next: encode(page[1]) }
    }
}

@Module({ controllers: [ItemsController] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const r = await http.get("/items")
    NOW += 5 * 60_000
    await http.get("/items?cursor=" + r.data.next)
    NOW += 20 * 60_000
    await http.get("/items?cursor=" + r.data.next)
    await http.close()
}
main()

