const products = Array.from({ length: 12 }, (_, i) => ({ id: i + 1, category: i % 3 === 0 ? "non" : "sut" }))
const fp = (filter: object) => createHash("sha1").update(JSON.stringify(filter)).digest("hex").slice(0, 8)

@Controller("products")
class ProductsController {
    @Get() list(@Query("category") category = "", @Query("cursor") cursor?: string) {
        const filter = { category }
        let after = 0
        if (cursor) {
            const [id, print] = cursor.split(":")
            if (print !== fp(filter)) throw new BadRequestException("Cursor boshqa filtr uchun berilgan")
            after = Number(id)
        }
        const page = products.filter(p => (!category || p.category === category) && p.id > after).slice(0, 2)
        return { ids: page.map(p => p.id), next: `${page[page.length - 1].id}:${fp(filter)}` }
    }
}

@Module({ controllers: [ProductsController] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const r = await http.get("/products?category=non")
    await http.get(`/products?category=non&cursor=${r.data.next}`)
    await http.get(`/products?category=sut&cursor=${r.data.next}`)
    await http.close()
}
