import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { InjectModel, MongooseModule, Prop, Schema, SchemaFactory } from "@nestjs/mongoose"
import { Model, Types } from "mongoose"

@Schema() class Note { @Prop() text: string }
const NoteSchema = SchemaFactory.createForClass(Note)

@Injectable()
class NotesService {
    constructor(@InjectModel(Note.name) private readonly model: Model<Note>) {}
    seed() { return this.model.insertMany(Array.from({ length: 7 }, (_, i) => ({ text: `eslatma-${i + 1}` }))) }
    async page(after?: string) {
        const filter = after ? { _id: { $gt: new Types.ObjectId(after) } } : {}
        const docs = await this.model.find(filter).sort({ _id: 1 }).limit(3).lean()
        return { items: docs.map(d => d.text), next: docs.length === 3 ? String(docs[2]._id) : null }
    }
}

async function main() {
    const uri = await startMongo()
    @Module({ imports: [MongooseModule.forRoot(uri), MongooseModule.forFeature([{ name: Note.name, schema: NoteSchema }])], providers: [NotesService] })
    class AppModule {}
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const s = app.get(NotesService)
    await s.seed()
    let next: string | null | undefined
    do {
        const r = await s.page(next ?? undefined)
        console.log(r.items)
        next = r.next
    } while (next)
    await app.close()
    await stopMongo()
}
main()

