import { BadRequestException, Controller, DefaultValuePipe, Get, Module, ParseIntPipe, Query } from "@nestjs/common"

const MAX_OFFSET = 10_000

@Controller("search")
class SearchController {
    @Get()
    search(@Query("page", new DefaultValuePipe(1), ParseIntPipe) page: number, @Query("size", new DefaultValuePipe(50), ParseIntPipe) size: number) {
        const offset = (page - 1) * size
        if (offset >= MAX_OFFSET) throw new BadRequestException(`Faqat dastlabki ${MAX_OFFSET} ta natija — qidiruvni aniqlashtiring`)
        return { offset, size }
    }
}

@Module({ controllers: [SearchController] }) class AppModule {}

async function main() {
