import { Controller, Get, Module, ParseIntPipe, Post, Query } from "@nestjs/common"

let clock = 100
const items = [1, 2, 3, 4, 5].map(id => ({ id, createdAt: clock++ }))

@Controller("items")
class ItemsController {
    @Post() add() { items.push({ id: items.length + 1, createdAt: clock++ }) }
    @Get()
    list(@Query("page", ParseIntPipe) page: number, @Query("asOf", new ParseIntPipe({ optional: true })) asOf?: number) {
        const snapshot = asOf ?? clock
        const visible = items.filter(i => i.createdAt < snapshot).sort((a, b) => b.createdAt - a.createdAt)
        return { asOf: snapshot, ids: visible.slice((page - 1) * 2, page * 2).map(i => i.id) }
    }
}

@Module({ controllers: [ItemsController] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const first = await http.get("/items?page=1")
    await http.post("/items")
    await http.post("/items")
    await http.get(`/items?page=2&asOf=${first.data.asOf}`)
    await http.get("/items?page=2")
    await http.close()
}
