import { Body, Controller, Delete, Get, HttpCode, Injectable, Module, NotFoundException, Param, ParseIntPipe, Post } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, ManyToOne, OneToMany, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Author {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @OneToMany(() => Book, book => book.author) books: Book[]
}

@Entity() class Book {
    @PrimaryGeneratedColumn() id: number
    @Column() title: string
    @Column() authorId: number                                    // tashqi kalitni ochiq maydon qilish qulay
    @ManyToOne(() => Author, a => a.books, { onDelete: "CASCADE" }) author: Author
}

@Injectable() class LibraryService {
    constructor(
        @InjectRepository(Author) private authors: Repository<Author>,
        @InjectRepository(Book) private books: Repository<Book>,
    ) {}

    createAuthor(name: string) { return this.authors.save({ name }) }

    async createBook(title: string, authorId: number) {
        const exists = await this.authors.existsBy({ id: authorId })
        if (!exists) throw new NotFoundException(`Muallif #${authorId} topilmadi`)
        return this.books.save({ title, authorId })
    }

    authorsWithBooks() {
        return this.authors.find({ relations: { books: true }, order: { id: "ASC", books: { id: "ASC" } } })
    }

    bookWithAuthor(id: number) {
        return this.books.findOne({ where: { id }, relations: { author: true } })
    }

    async removeAuthor(id: number) {
        const res = await this.authors.delete(id)
        if (!res.affected) throw new NotFoundException()
    }

    countBooks() { return this.books.count() }
}

@Controller() class LibraryController {
    constructor(private s: LibraryService) {}
    @Post("authors") createAuthor(@Body("name") name: string) { return this.s.createAuthor(name) }
    @Post("books") createBook(@Body() b: { title: string; authorId: number }) { return this.s.createBook(b.title, b.authorId) }
    @Get("authors") authors() { return this.s.authorsWithBooks() }
    @Get("books/:id") book(@Param("id", ParseIntPipe) id: number) { return this.s.bookWithAuthor(id) }
    @Delete("authors/:id") @HttpCode(204) remove(@Param("id", ParseIntPipe) id: number) { return this.s.removeAuthor(id) }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Author, Book], synchronize: true }), TypeOrmModule.forFeature([Author, Book])],
    controllers: [LibraryController], providers: [LibraryService],
})
