@Entity() class Invoice {
    @PrimaryGeneratedColumn() id: number
    @Column() customer: string
    @OneToMany(() => InvoiceLine, l => l.invoice, { cascade: true })     // ota bilan birga saqlanadi
    lines: InvoiceLine[]
