@Injectable() class InvoicesService {
    constructor(@InjectRepository(Invoice) private repo: Repository<Invoice>) {}

    create(data: { customer: string; lines: { item: string; qty: number; price: number }[] }) {
        return this.repo.save(this.repo.create(data))           // bitta save — hamma satrlar ham
    }

    async findOne(id: number) {
        const inv = await this.repo.findOne({ where: { id }, relations: { lines: true } })
        const total = inv!.lines.reduce((s, l) => s + l.qty * l.price, 0)
        return { customer: inv!.customer, lines: inv!.lines.map(l => `${l.item} x${l.qty}`), total }
    }
}

