import { Column, Entity, ManyToOne, OneToMany, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Category {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @OneToMany(() => Product, p => p.category) products: Product[]
}

@Entity() class Product {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @Column("int") price: number
    @ManyToOne(() => Category, c => c.products) category: Category
}

@Injectable() class CatalogService {
    constructor(@InjectRepository(Category) private cats: Repository<Category>, @InjectRepository(Product) private prods: Repository<Product>) {}

    async seed() {
        const [tech, clothes, books] = await this.cats.save([{ name: "Texnika" }, { name: "Kiyim" }, { name: "Kitoblar" }])
        await this.prods.save([
            { name: "Noutbuk", price: 9000, category: tech }, { name: "Telefon", price: 4000, category: tech },
            { name: "Planshet", price: 3000, category: tech }, { name: "Ko'ylak", price: 300, category: clothes },
        ])
        void books
    }

    summary() {
        return this.cats.createQueryBuilder("c")
            .leftJoin("c.products", "p")
            .select("c.name", "category")
            .addSelect("COUNT(p.id)", "products")
            .addSelect("COALESCE(AVG(p.price), 0)", "avgPrice")
            .groupBy("c.id")
            .orderBy("products", "DESC")
            .getRawMany()
    }
}

