        await this.emps.save([{ name: "Aziz", departmentId: 1 }, { name: "Laylo", departmentId: 1 }])
    }

    async transfer(employeeId: number, departmentId: number) {
        if (!(await this.deps.existsBy({ id: departmentId }))) throw new NotFoundException("Bo'lim topilmadi")
        await this.emps.update(employeeId, { departmentId })
        return this.emps.findOne({ where: { id: employeeId }, relations: { department: true } })
    }

    structure() {
        return this.deps.find({ relations: { employees: true }, order: { id: "ASC" } })
            .then(ds => ds.map(d => `${d.name}: ${d.employees.map(e => e.name).join(", ") || "—"}`))
    }
}

