import { Controller, Get, Injectable, Module } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, ManyToOne, OneToMany, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Author {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @OneToMany(() => Book, b => b.author) books: Book[]
}
@Entity() class Book {
    @PrimaryGeneratedColumn() id: number
    @Column() title: string
    @ManyToOne(() => Author, a => a.books) author: Author
}

@Injectable()
class AuthorsService {
    constructor(@InjectRepository(Author) private readonly authors: Repository<Author>, @InjectRepository(Book) private readonly books: Repository<Book>) {}
    async seed() {
        const [a, b] = await this.authors.save([{ name: "Qodiriy" }, { name: "Oybek" }])
        await this.books.save([{ title: "O'tkan kunlar", author: a }, { title: "Mehrobdan chayon", author: a }, { title: "Navoiy", author: b }])
    }
    withCounts() {
        return this.authors.createQueryBuilder("a")
            .leftJoin("a.books", "b")
            .select("a.name", "name")
            .addSelect("COUNT(b.id)", "books")
            .groupBy("a.id")
            .orderBy("books", "DESC")
            .getRawMany()
    }
}

@Controller("authors")
class AuthorsController {
    constructor(private readonly s: AuthorsService) {}
    @Get("counts") counts() { return this.s.withCounts() }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Author, Book], synchronize: true }), TypeOrmModule.forFeature([Author, Book])],
    controllers: [AuthorsController], providers: [AuthorsService],
})
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.app.get(AuthorsService).seed()
    await http.get("/authors/counts")
    await http.close()
}
main()

import { Controller, Get, Injectable, Module, Param, ParseIntPipe, Query } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, ManyToOne, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Channel { @PrimaryGeneratedColumn() id: number; @Column() name: string }
@Entity() class Message {
    @PrimaryGeneratedColumn() id: number
    @Column() text: string
    @Column() channelId: number
    @ManyToOne(() => Channel) channel: Channel
}

@Injectable()
class ChatService {
    constructor(@InjectRepository(Channel) private readonly channels: Repository<Channel>, @InjectRepository(Message) private readonly messages: Repository<Message>) {}
    async seed() {
        await this.channels.save({ name: "general" })
        await this.messages.save(Array.from({ length: 8 }, (_, i) => ({ channelId: 1, text: `xabar ${i + 1}` })))
    }
    async page(channelId: number, page: number, limit: number) {
        const [data, total] = await this.messages.findAndCount({
            where: { channelId }, order: { id: "DESC" }, skip: (page - 1) * limit, take: limit, select: { text: true },
        })
        return { data: data.map(m => m.text), meta: { page, limit, total } }
    }
}

@Controller("channels/:id/messages")
class ChatController {
    constructor(private readonly s: ChatService) {}
    @Get() list(@Param("id", ParseIntPipe) id: number, @Query("page") page = "1", @Query("limit") limit = "3") {
        return this.s.page(id, +page, +limit)
    }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Channel, Message], synchronize: true }), TypeOrmModule.forFeature([Channel, Message])],
    controllers: [ChatController], providers: [ChatService],
})
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.app.get(ChatService).seed()
    await http.get("/channels/1/messages")
    await http.get("/channels/1/messages?page=3")
    await http.close()
}
