import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, ManyToOne, OneToMany, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Team {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @OneToMany(() => Player, p => p.team) players: Player[]
}
@Entity() class Player {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @ManyToOne(() => Team, t => t.players) team: Team
}

@Injectable()
class Demo {
    private queries = 0
    constructor(@InjectRepository(Team) private readonly teams: Repository<Team>, @InjectRepository(Player) private readonly players: Repository<Player>) {}
    async run() {
        const [a, b] = await this.teams.save([{ name: "Paxtakor" }, { name: "Bunyodkor" }])
        await this.players.save([{ name: "Ali", team: a }, { name: "Vali", team: a }, { name: "Bek", team: b }])

        // ✘ N+1: har bir jamoa uchun alohida so'rov
        let n = 0
        const teams = await this.teams.find()
        n++
        for (const t of teams) { await this.players.findBy({ team: { id: t.id } }); n++ }
        console.log("N+1 usulida so'rovlar soni:", n)

        // ✔ bitta so'rov
        const withPlayers = await this.teams.find({ relations: { players: true } })
        console.log("relations bilan: 1 ta so'rov →", withPlayers.map(t => `${t.name}: ${t.players.length}`))
    }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Team, Player], synchronize: true }), TypeOrmModule.forFeature([Team, Player])],
    providers: [Demo],
})
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    await app.get(Demo).run()
    await app.close()
}
