import { Controller, Get, Injectable, Module } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, ManyToOne, OneToMany, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Post_ {
    @PrimaryGeneratedColumn() id: number
    @Column() title: string
    @OneToMany(() => Comment, c => c.post) comments: Comment[]
}
@Entity() class Comment {
    @PrimaryGeneratedColumn() id: number
    @Column() text: string
    @ManyToOne(() => Post_, p => p.comments) post: Post_
}

@Injectable()
class PostsService {
    constructor(@InjectRepository(Post_) private readonly posts: Repository<Post_>, @InjectRepository(Comment) private readonly comments: Repository<Comment>) {}
    async seed() {
        const [p1, p2, p3] = await this.posts.save([{ title: "Birinchi" }, { title: "Ikkinchi" }, { title: "Uchinchi" }])
        await this.comments.save([{ text: "a", post: p1 }, { text: "b", post: p3 }])
    }
    withComments() {
        return this.posts.createQueryBuilder("p").innerJoin("p.comments", "c").select("p.title", "title").distinct(true).getRawMany()
    }
    withoutComments() {
        return this.posts.createQueryBuilder("p").leftJoin("p.comments", "c").where("c.id IS NULL").select("p.title", "title").getRawMany()
    }
}

@Controller("posts")
class PostsController {
    constructor(private readonly s: PostsService) {}
    @Get("with") with_() { return this.s.withComments() }
    @Get("without") without() { return this.s.withoutComments() }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Post_, Comment], synchronize: true }), TypeOrmModule.forFeature([Post_, Comment])],
    controllers: [PostsController], providers: [PostsService],
})
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.app.get(PostsService).seed()
    await http.get("/posts/with")
    await http.get("/posts/without")
    await http.close()
}
