import { Controller, Get, Injectable, Module } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, ManyToOne, OneToMany, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Order { @PrimaryGeneratedColumn() id: number; @Column() customer: string; @OneToMany(() => Line, l => l.order) lines: Line[] }
@Entity() class Line {
    @PrimaryGeneratedColumn() id: number
    @Column() product: string
    @Column("int") qty: number
    @Column("int") price: number
    @ManyToOne(() => Order, o => o.lines) order: Order
}

@Injectable()
class OrdersService {
    constructor(@InjectRepository(Order) private readonly orders: Repository<Order>, @InjectRepository(Line) private readonly lines: Repository<Line>) {}
    async seed() {
        const o = await this.orders.save({ customer: "Laylo" })
        await this.lines.save([{ product: "Choy", qty: 2, price: 25000, order: o }, { product: "Non", qty: 3, price: 4000, order: o }])
    }
    async summary() {
        const orders = await this.orders.find({ relations: { lines: true } })
        return orders.map(o => ({
            id: o.id,
            customer: o.customer,
            items: o.lines.length,
            total: o.lines.reduce((s, l) => s + l.qty * l.price, 0),
        }))
    }
}

@Controller("orders")
class OrdersController {
    constructor(private readonly s: OrdersService) {}
    @Get("summary") summary() { return this.s.summary() }
}

