@Injectable()
class TasksService {
    constructor(@InjectRepository(Board) private readonly boards: Repository<Board>, @InjectRepository(Task) private readonly tasks: Repository<Task>) {}
    async run() {
        const [todo, done] = await this.boards.save([{ name: "Bajarilmoqda" }, { name: "Tugallangan" }])
        const task = await this.tasks.save({ title: "Hisobot", boardId: todo.id })
        console.log("boshlang'ich doska:", (await this.boards.findOneByOrFail({ id: task.boardId })).name)

        await this.tasks.update(task.id, { boardId: done.id })
        const moved = await this.tasks.findOneOrFail({ where: { id: task.id }, relations: { board: true } })
        console.log("ko'chirilgandan keyin:", moved.board.name)
    }
}

