import { Body, Controller, Module, NotFoundException, Param, ParseIntPipe, Post } from "@nestjs/common"

const authors = [{ id: 1, name: "Qodiriy" }]
const books: { id: number; authorId: number; title: string }[] = []

@Controller("authors/:authorId/books")
class AuthorBooksController {
    @Post()
    create(@Param("authorId", ParseIntPipe) authorId: number, @Body("title") title: string) {
        const author = authors.find(a => a.id === authorId)
        if (!author) throw new NotFoundException(`Muallif #${authorId} topilmadi`)
        const book = { id: books.length + 1, authorId, title }
        books.push(book)
        return { ...book, author: author.name }
    }
}

