import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, ManyToOne, PrimaryGeneratedColumn, Relation, Repository } from "typeorm"

@Entity() class Author { @PrimaryGeneratedColumn() id: number; @Column() name: string; @Column({ default: 0 }) booksCount: number }
@Entity() class Book { @PrimaryGeneratedColumn() id: number; @Column() title: string; @ManyToOne(() => Author) author: Relation<Author> }

@Injectable()
class BooksService {
    constructor(private readonly ds: DataSource, @InjectRepository(Author) private readonly authors: Repository<Author>) {}
    add(authorId: number, title: string) {
        return this.ds.transaction(async em => {
            await em.save(Book, { title, author: { id: authorId } })
            await em.increment(Author, { id: authorId }, "booksCount", 1)
        })
    }
    async remove(bookId: number) {
        await this.ds.transaction(async em => {
            const book = await em.findOne(Book, { where: { id: bookId }, relations: { author: true } })
            await em.delete(Book, bookId)
            await em.decrement(Author, { id: book!.author.id }, "booksCount", 1)
        })
    }
    list() { return this.authors.find().then(a => a.map(x => `${x.name}: ${x.booksCount}`)) }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Author, Book], synchronize: true }), TypeOrmModule.forFeature([Author])], providers: [BooksService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    await app.get(DataSource).getRepository(Author).save({ name: "Qodiriy" })
    const s = app.get(BooksService)
    await s.add(1, "O'tkan kunlar"); await s.add(1, "Mehrobdan chayon"); await s.add(1, "Obid ketmon")
    await s.remove(2)
    console.log(await s.list())
    await app.close()
}
main()

