import { Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { getModelToken, MongooseModule, Prop, Schema, SchemaFactory } from "@nestjs/mongoose"
import { Model, Types } from "mongoose"

@Schema({ toJSON: { virtuals: true }, toObject: { virtuals: true } }) class Author { @Prop() name: string }
const AuthorSchema = SchemaFactory.createForClass(Author)
AuthorSchema.virtual("books", { ref: "Book", localField: "_id", foreignField: "author" })

@Schema() class Book { @Prop() title: string; @Prop({ type: Types.ObjectId, ref: "Author" }) author: Types.ObjectId }
const BookSchema = SchemaFactory.createForClass(Book)

async function main() {
    const uri = await startMongo()
    @Module({ imports: [MongooseModule.forRoot(uri), MongooseModule.forFeature([{ name: "Author", schema: AuthorSchema }, { name: "Book", schema: BookSchema }])] })
    class AppModule {}
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const authors = app.get<Model<Author>>(getModelToken("Author"))
    const books = app.get<Model<Book>>(getModelToken("Book"))
    const q = await authors.create({ name: "Qodiriy" })
    await books.create([{ title: "O'tkan kunlar", author: q._id }, { title: "Mehrobdan chayon", author: q._id }])
    const doc = await authors.findById(q._id).populate<{ books: Book[] }>({ path: "books", options: { sort: { title: 1 } } })
