@Entity() class Cart { @PrimaryGeneratedColumn() id: number; @Column() owner: string }
@Entity() class CartItem { @PrimaryGeneratedColumn() id: number; @Column() item: string; @ManyToOne(() => Cart, { onDelete: "CASCADE" }) cart: Relation<Cart> }

@Injectable()
class CartService {
    constructor(private readonly ds: DataSource) {}
    removeItem(itemId: number) {
        return this.ds.transaction(async em => {
            const item = await em.findOne(CartItem, { where: { id: itemId }, relations: { cart: true } })
            await em.delete(CartItem, itemId)
            const left = await em.countBy(CartItem, { cart: { id: item!.cart.id } })
            if (left === 0) await em.delete(Cart, item!.cart.id)
            return { left, cartDeleted: left === 0 }
        })
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Cart, CartItem], synchronize: true })], providers: [CartService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const ds = app.get(DataSource)
    const cart = await ds.getRepository(Cart).save({ owner: "Ali" })
    await ds.getRepository(CartItem).save([{ item: "Non", cart }, { item: "Sut", cart }])
    const s = app.get(CartService)
    console.log(await s.removeItem(1))
    console.log(await s.removeItem(2))
    console.log("savatlar:", await ds.getRepository(Cart).count())
    await app.close()
}
