import { Body, Controller, Get, Injectable, Module, NotFoundException, Param, ParseIntPipe, Patch, Post } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, JoinColumn, OneToOne, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Profile {
    @PrimaryGeneratedColumn() id: number
    @Column({ nullable: true }) bio: string
    @Column({ nullable: true }) city: string
}

@Entity() class User {
    @PrimaryGeneratedColumn() id: number
    @Column() email: string
    @OneToOne(() => Profile, { cascade: true, eager: true })      // eager — doim birga yuklanadi
    @JoinColumn()                                                  // profileId ustuni users jadvalida
    profile: Profile
}

@Injectable() class UsersService {
    constructor(@InjectRepository(User) private repo: Repository<User>) {}

    create(email: string, profile: Partial<Profile>) {
        return this.repo.save(this.repo.create({ email, profile }))    // profil ham avtomatik saqlanadi
    }

    async findOne(id: number) {
        const user = await this.repo.findOneBy({ id })
        if (!user) throw new NotFoundException()
        return user
    }

    async updateProfile(id: number, changes: Partial<Profile>) {
        const user = await this.findOne(id)
        Object.assign(user.profile, changes)
        return this.repo.save(user)                                    // cascade — profil yangilanadi
    }
}

@Controller("users") class UsersController {
    constructor(private s: UsersService) {}
    @Post() create(@Body() b: { email: string; profile: Partial<Profile> }) { return this.s.create(b.email, b.profile) }
    @Get(":id") one(@Param("id", ParseIntPipe) id: number) { return this.s.findOne(id) }
    @Patch(":id/profile") update(@Param("id", ParseIntPipe) id: number, @Body() b: Partial<Profile>) { return this.s.updateProfile(id, b) }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [User, Profile], synchronize: true }), TypeOrmModule.forFeature([User])],
    controllers: [UsersController], providers: [UsersService],
})
