@Entity() class User {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @OneToOne(() => Passport, p => p.user) passport: Passport | null
}

@Entity() class Passport {
    @PrimaryGeneratedColumn() id: number
    @Column() series: string
    @Column({ unique: true }) userId: number
    @OneToOne(() => User, u => u.passport, { onDelete: "CASCADE" })
    @JoinColumn({ name: "userId" })                                    // tashqi kalit passport jadvalida
    user: User
}

@Injectable() class PassportService {
    constructor(@InjectRepository(User) private users: Repository<User>, @InjectRepository(Passport) private passports: Repository<Passport>) {}

    async upsert(userId: number, series: string) {
        if (!(await this.users.existsBy({ id: userId }))) throw new NotFoundException("Foydalanuvchi yo'q")
        const existing = await this.passports.findOneBy({ userId })
        const saved = await this.passports.save({ ...existing, userId, series })
        return { action: existing ? "yangilandi" : "yaratildi", passport: { series: saved.series } }
    }

    user(id: number) { return this.users.findOne({ where: { id }, relations: { passport: true } }) }
    seed() { return this.users.save({ name: "Sardor" }) }
}

@Controller("users/:id") class PassportController {
    constructor(private s: PassportService) {}
    @Put("passport") upsert(@Param("id", ParseIntPipe) id: number, @Body("series") series: string) { return this.s.upsert(id, series) }
    @Get() user(@Param("id", ParseIntPipe) id: number) { return this.s.user(id) }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [User, Passport], synchronize: true }), TypeOrmModule.forFeature([User, Passport])],
    controllers: [PassportController], providers: [PassportService],
})
class AppModule {}

