    const http = await testApp(AppModule)
    await http.app.get(PassportService).seed()
    await http.get("/users/1")
    await http.put("/users/1/passport", { series: "AA1234567" })
    await http.put("/users/1/passport", { series: "AB7654321" })
    await http.get("/users/1")
    await http.close()
}
