import { Body, Controller, Get, Injectable, Module, NotFoundException, Param, ParseIntPipe, Put } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, JoinColumn, OneToOne, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Profile {
    @PrimaryGeneratedColumn() id: number
    @Column({ default: "" }) bio: string
    @Column({ default: "uz" }) lang: string
}
@Entity() class User {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @OneToOne(() => Profile, { cascade: true, eager: true }) @JoinColumn() profile: Profile
}

@Injectable()
class ProfilesService {
    constructor(@InjectRepository(User) private readonly users: Repository<User>) {}
    seed() { return this.users.save({ name: "Ali", profile: {} } as User) }
    async get(userId: number) {
        const user = await this.users.findOneBy({ id: userId })
        if (!user) throw new NotFoundException("Foydalanuvchi yo'q")
        return user.profile
    }
    async replace(userId: number, data: { bio: string; lang: string }) {
        const user = await this.users.findOneByOrFail({ id: userId })
        Object.assign(user.profile, data)
        await this.users.save(user)
        return user.profile
    }
}

@Controller("users/:id/profile")
class ProfilesController {
    constructor(private readonly s: ProfilesService) {}
    @Get() get(@Param("id", ParseIntPipe) id: number) { return this.s.get(id) }
    @Put() put(@Param("id", ParseIntPipe) id: number, @Body() b: { bio: string; lang: string }) { return this.s.replace(id, b) }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [User, Profile], synchronize: true }), TypeOrmModule.forFeature([User])],
    controllers: [ProfilesController], providers: [ProfilesService],
})
