@Entity() class Wallet { @PrimaryGeneratedColumn() id: number; @Column({ default: 0 }) balance: number }
@Entity() class User { @PrimaryGeneratedColumn() id: number; @Column() name: string; @OneToOne(() => Wallet, { cascade: true, eager: true }) @JoinColumn() wallet: Relation<Wallet> }

@Injectable()
class WalletService {
    constructor(private readonly ds: DataSource) {}
    register(name: string) { return this.ds.getRepository(User).save({ name, wallet: { balance: 10000 } }) } // bonus
    async pay(userId: number, amount: number) {
        const user = (await this.ds.getRepository(User).findOneBy({ id: userId }))!
        if (user.wallet.balance < amount) throw new BadRequestException(`Balans yetarli emas: ${user.wallet.balance}`)
        await this.ds.getRepository(Wallet).decrement({ id: user.wallet.id }, "balance", amount)
        return (await this.ds.getRepository(User).findOneBy({ id: userId }))!.wallet.balance
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [User, Wallet], synchronize: true })], providers: [WalletService] })
