import { Body, Controller, Delete, Get, Injectable, Module, NotFoundException, Param, ParseIntPipe, Post } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, JoinTable, ManyToMany, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Course {
    @PrimaryGeneratedColumn() id: number
    @Column() title: string
    @ManyToMany(() => Student, s => s.courses) students: Student[]
}

@Entity() class Student {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @ManyToMany(() => Course, c => c.students)
    @JoinTable()                                                  // oraliq jadval: student_courses_course
    courses: Course[]
}

@Injectable() class EnrollmentService {
    constructor(@InjectRepository(Student) private students: Repository<Student>, @InjectRepository(Course) private courses: Repository<Course>) {}

    async seed() {
        await this.students.save([{ name: "Aziza" }, { name: "Bekzod" }])
        await this.courses.save([{ title: "NestJS" }, { title: "React" }, { title: "SQL" }])
    }

    private async student(id: number) {
        const s = await this.students.findOne({ where: { id }, relations: { courses: true } })
        if (!s) throw new NotFoundException("Talaba topilmadi")
        return s
    }

    async enroll(studentId: number, courseId: number) {
        const student = await this.student(studentId)
        const course = await this.courses.findOneBy({ id: courseId })
        if (!course) throw new NotFoundException("Kurs topilmadi")
        if (!student.courses.some(c => c.id === courseId)) student.courses.push(course)
        await this.students.save(student)
        return { student: student.name, courses: student.courses.map(c => c.title) }
    }

    async unenroll(studentId: number, courseId: number) {
        const student = await this.student(studentId)
        student.courses = student.courses.filter(c => c.id !== courseId)
        await this.students.save(student)
        return { student: student.name, courses: student.courses.map(c => c.title) }
    }

    async courseStudents(courseId: number) {
        const c = await this.courses.findOne({ where: { id: courseId }, relations: { students: true } })
        return { course: c!.title, students: c!.students.map(s => s.name) }
    }
}

@Controller() class EnrollmentController {
    constructor(private s: EnrollmentService) {}
    @Post("students/:sid/courses/:cid") enroll(@Param("sid", ParseIntPipe) s: number, @Param("cid", ParseIntPipe) c: number) { return this.s.enroll(s, c) }
    @Delete("students/:sid/courses/:cid") unenroll(@Param("sid", ParseIntPipe) s: number, @Param("cid", ParseIntPipe) c: number) { return this.s.unenroll(s, c) }
    @Get("courses/:id/students") list(@Param("id", ParseIntPipe) id: number) { return this.s.courseStudents(id) }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Student, Course], synchronize: true }), TypeOrmModule.forFeature([Student, Course])],
    controllers: [EnrollmentController], providers: [EnrollmentService],
})
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.app.get(EnrollmentService).seed()
    await http.post("/students/1/courses/1")
    await http.post("/students/1/courses/3")
    await http.post("/students/2/courses/1")
    await http.post("/students/1/courses/1")          // takroriy yozilish — e'tiborsiz
    await http.get("/courses/1/students")
    await http.delete("/students/1/courses/1")
    await http.get("/courses/1/students")
    await http.close()
}
