import { Body, Controller, Get, Injectable, Module, Post, Query } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, In, JoinTable, ManyToMany, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Tag {
    @PrimaryGeneratedColumn() id: number
    @Column({ unique: true }) name: string
}

@Entity() class Product {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @ManyToMany(() => Tag, { cascade: true }) @JoinTable() tags: Tag[]
}

@Injectable() class ProductsService {
    constructor(@InjectRepository(Product) private products: Repository<Product>, @InjectRepository(Tag) private tags: Repository<Tag>) {}

    private async resolveTags(names: string[]) {
        const existing = await this.tags.findBy({ name: In(names) })
        const missing = names.filter(n => !existing.some(t => t.name === n))
        return [...existing, ...missing.map(name => this.tags.create({ name }))]    // yangilari cascade bilan saqlanadi
    }

    async create(name: string, tagNames: string[]) {
        const product = await this.products.save({ name, tags: await this.resolveTags(tagNames) })
        return { name: product.name, tags: product.tags.map(t => t.name) }
    }

    async byTag(tag: string) {
        const list = await this.products.find({ where: { tags: { name: tag } }, relations: { tags: true } })
        return list.map(p => p.name)
    }

    tagCount() { return this.tags.count() }
}

@Controller("products") class ProductsController {
    constructor(private s: ProductsService) {}
    @Post() create(@Body() b: { name: string; tags: string[] }) { return this.s.create(b.name, b.tags) }
    @Get() byTag(@Query("tag") tag: string) { return this.s.byTag(tag) }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Product, Tag], synchronize: true }), TypeOrmModule.forFeature([Product, Tag])],
    controllers: [ProductsController], providers: [ProductsService],
})
