import { Body, Controller, Get, Injectable, Module, NotFoundException, Param, ParseIntPipe, Post } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, In, ManyToOne, OneToMany, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Product {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @Column("int") price: number
}

@Entity() class Order {
    @PrimaryGeneratedColumn() id: number
    @Column() customer: string
    @OneToMany(() => OrderItem, i => i.order, { cascade: true }) items: OrderItem[]
}

@Entity() class OrderItem {
    @PrimaryGeneratedColumn() id: number
    @ManyToOne(() => Order, o => o.items, { onDelete: "CASCADE" }) order: Order
    @ManyToOne(() => Product, { eager: true }) product: Product
    @Column("int") qty: number
    @Column("int") unitPrice: number          // buyurtma paytidagi narx — keyin mahsulot narxi o'zgarsa ham saqlanadi
}

@Injectable() class OrdersService {
    constructor(@InjectRepository(Order) private orders: Repository<Order>, @InjectRepository(Product) private products: Repository<Product>) {}

    seed() { return this.products.save([{ name: "Kofe", price: 25000 }, { name: "Pishiriq", price: 18000 }]) }

    async create(customer: string, items: { productId: number; qty: number }[]) {
        const products = await this.products.findBy({ id: In(items.map(i => i.productId)) })
        const lines = items.map(i => {
            const product = products.find(p => p.id === i.productId)
            if (!product) throw new NotFoundException(`Mahsulot #${i.productId} yo'q`)
            return { product, qty: i.qty, unitPrice: product.price }
        })
        const order = await this.orders.save(this.orders.create({ customer, items: lines }))
        return this.view(order.id)
    }

    async view(id: number) {
        const o = await this.orders.findOne({ where: { id }, relations: { items: true } })
        return {
            customer: o!.customer,
            items: o!.items.map(i => `${i.product.name} x${i.qty} = ${i.qty * i.unitPrice}`),
            total: o!.items.reduce((s, i) => s + i.qty * i.unitPrice, 0),
        }
    }

    changePrice(id: number, price: number) { return this.products.update(id, { price }) }
}

@Controller("orders") class OrdersController {
    constructor(private s: OrdersService) {}
    @Post() create(@Body() b: { customer: string; items: { productId: number; qty: number }[] }) { return this.s.create(b.customer, b.items) }
    @Get(":id") view(@Param("id", ParseIntPipe) id: number) { return this.s.view(id) }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Product, Order, OrderItem], synchronize: true }), TypeOrmModule.forFeature([Product, Order])],
    controllers: [OrdersController], providers: [OrdersService],
})
class AppModule {}

