import { Body, Controller, Injectable, Module, Param, ParseIntPipe, Put } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, In, JoinTable, ManyToMany, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Role { @PrimaryGeneratedColumn() id: number; @Column() name: string }

@Entity() class User {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @ManyToMany(() => Role) @JoinTable() roles: Role[]
}

@Injectable() class UsersService {
    constructor(@InjectRepository(User) private users: Repository<User>, @InjectRepository(Role) private roles: Repository<Role>) {}

    async seed() {
        await this.roles.save([{ name: "viewer" }, { name: "editor" }, { name: "admin" }])
        const viewer = await this.roles.findOneByOrFail({ name: "viewer" })
        await this.users.save({ name: "Olim", roles: [viewer] })
    }

    async setRoles(userId: number, roleNames: string[]) {
        const user = await this.users.findOneOrFail({ where: { id: userId }, relations: { roles: true } })
        const before = user.roles.map(r => r.name)
        user.roles = await this.roles.findBy({ name: In(roleNames) })     // eski bog'lanishlar o'chadi, yangilari qo'shiladi
        await this.users.save(user)
        return { before, after: user.roles.map(r => r.name) }
    }
}

@Controller("users") class UsersController {
    constructor(private s: UsersService) {}
    @Put(":id/roles") set(@Param("id", ParseIntPipe) id: number, @Body("roles") roles: string[]) { return this.s.setRoles(id, roles) }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [User, Role], synchronize: true }), TypeOrmModule.forFeature([User, Role])],
    controllers: [UsersController], providers: [UsersService],
})
class AppModule {}

