import { Body, Controller, Delete, Get, Injectable, Module, Param, ParseIntPipe, Post } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, JoinTable, ManyToMany, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Tag { @PrimaryGeneratedColumn() id: number; @Column({ unique: true }) name: string }
@Entity() class Article {
    @PrimaryGeneratedColumn() id: number
    @Column() title: string
    @ManyToMany(() => Tag, { eager: true }) @JoinTable() tags: Tag[]
}

@Injectable()
class ArticlesService {
    constructor(
        @InjectRepository(Article) private readonly articles: Repository<Article>,
        @InjectRepository(Tag) private readonly tags: Repository<Tag>,
        private readonly ds: DataSource,
    ) {}
    async seed() {
        await this.tags.save([{ name: "nestjs" }, { name: "typescript" }, { name: "eski" }])
        return this.articles.save({ title: "Maqola", tags: [] } as unknown as Article)
    }
    async addTag(articleId: number, name: string) {
        const tag = await this.tags.findOneByOrFail({ name })
        await this.ds.createQueryBuilder().relation(Article, "tags").of(articleId).add(tag.id)
        return this.articles.findOneBy({ id: articleId })
    }
    async removeTag(articleId: number, name: string) {
        const tag = await this.tags.findOneByOrFail({ name })
        await this.ds.createQueryBuilder().relation(Article, "tags").of(articleId).remove(tag.id)
        return this.articles.findOneBy({ id: articleId })
    }
}

@Controller("articles/:id/tags")
class TagsController {
    constructor(private readonly s: ArticlesService) {}
    @Post() add(@Param("id", ParseIntPipe) id: number, @Body("name") name: string) { return this.s.addTag(id, name) }
    @Delete(":name") remove(@Param("id", ParseIntPipe) id: number, @Param("name") name: string) { return this.s.removeTag(id, name) }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Article, Tag], synchronize: true }), TypeOrmModule.forFeature([Article, Tag])],
    controllers: [TagsController], providers: [ArticlesService],
})
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.app.get(ArticlesService).seed()
    await http.post("/articles/1/tags", { name: "nestjs" })
    await http.post("/articles/1/tags", { name: "eski" })
    await http.delete("/articles/1/tags/eski")
    await http.close()
}
