import { Controller, Get, Injectable, Module } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, CreateDateColumn, Entity, ManyToOne, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Student { @PrimaryGeneratedColumn() id: number; @Column() name: string }
@Entity() class Course { @PrimaryGeneratedColumn() id: number; @Column() title: string }
@Entity() class Enrollment {
    @PrimaryGeneratedColumn() id: number
    @ManyToOne(() => Student, { eager: true }) student: Student
    @ManyToOne(() => Course, { eager: true }) course: Course
    @Column("int", { nullable: true }) grade: number | null   // qo'shimcha maydon
    @CreateDateColumn() enrolledAt: Date
}

@Injectable()
class EnrollmentsService {
    constructor(
        @InjectRepository(Student) private readonly students: Repository<Student>,
        @InjectRepository(Course) private readonly courses: Repository<Course>,
        @InjectRepository(Enrollment) private readonly enrollments: Repository<Enrollment>,
    ) {}
    async seed() {
        const [ali, laylo] = await this.students.save([{ name: "Ali" }, { name: "Laylo" }])
        const [nest, ts] = await this.courses.save([{ title: "NestJS" }, { title: "TypeScript" }])
        await this.enrollments.save([
            { student: ali, course: nest, grade: 5 },
            { student: ali, course: ts, grade: null },
            { student: laylo, course: nest, grade: 4 },
        ])
    }
    async all() {
        return (await this.enrollments.find()).map(e => `${e.student.name} — ${e.course.title} (baho: ${e.grade ?? "yo'q"})`)
    }
}

@Controller("enrollments")
class EnrollmentsController {
    constructor(private readonly s: EnrollmentsService) {}
    @Get() all() { return this.s.all() }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Student, Course, Enrollment], synchronize: true }), TypeOrmModule.forFeature([Student, Course, Enrollment])],
