@Entity() class Tag { @PrimaryGeneratedColumn() id: number; @Column() name: string }
@Entity() class Note {
    @PrimaryGeneratedColumn() id: number
    @Column() title: string
    @ManyToMany(() => Tag, { cascade: true }) @JoinTable() tags: Tag[]
}

@Injectable()
class NotesService {
    constructor(@InjectRepository(Note) private readonly notes: Repository<Note>, @InjectRepository(Tag) private readonly tags: Repository<Tag>) {}
    async seed() {
        const [work, home, urgent] = await this.tags.save([{ name: "ish" }, { name: "uy" }, { name: "shoshilinch" }])
        await this.notes.save([
            { title: "Hisobot", tags: [work, urgent] },
            { title: "Non olish", tags: [home] },
            { title: "Uchrashuv", tags: [work] },
        ] as Note[])
    }
    cloud() {
        return this.tags.createQueryBuilder("t")
            .leftJoin("note_tags_tag", "nt", "nt.tagId = t.id")
            .select("t.name", "tag")
            .addSelect("COUNT(nt.noteId)", "count")
            .groupBy("t.id")
            .orderBy("count", "DESC")
            .getRawMany()
    }
}

