import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { InjectModel, MongooseModule, Prop, Schema, SchemaFactory } from "@nestjs/mongoose"
import { Model, Types } from "mongoose"

@Schema({ versionKey: false }) class Group { @Prop() name: string; @Prop({ type: [Types.ObjectId], ref: "Student", default: [] }) students: Types.ObjectId[] }
const GroupSchema = SchemaFactory.createForClass(Group)

@Schema({ versionKey: false }) class Student { @Prop() name: string }
const StudentSchema = SchemaFactory.createForClass(Student)

@Injectable()
class Demo {
    constructor(@InjectModel("Group") private readonly groups: Model<Group>, @InjectModel("Student") private readonly students: Model<Student>) {}
    async run() {
        const [ali, laylo] = await this.students.create([{ name: "Ali" }, { name: "Laylo" }])
        const g1 = await this.groups.create({ name: "Backend", students: [ali._id, laylo._id] })
        await this.groups.create({ name: "Frontend", students: [laylo._id] })

        const populated = await this.groups.findById(g1._id).populate<{ students: Student[] }>("students", "name -_id").lean()
        console.log(populated!.name, "→", populated!.students.map(s => s.name))

        const laylosGroups = await this.groups.find({ students: laylo._id }, { _id: 0, name: 1 }).lean()
        console.log("Laylo guruhlari:", laylosGroups.map(g => g.name))
    }
}

@Module({
    imports: [
        MongooseModule.forRootAsync({ useFactory: async () => ({ uri: await startMongo() }) }),
        MongooseModule.forFeature([{ name: "Group", schema: GroupSchema }, { name: "Student", schema: StudentSchema }]),
    ],
    providers: [Demo],
})
