import { Controller, Get, Injectable, Module } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, JoinTable, ManyToMany, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Tag { @PrimaryGeneratedColumn() id: number; @Column() name: string }
@Entity() class Recipe {
    @PrimaryGeneratedColumn() id: number
    @Column() title: string
    @ManyToMany(() => Tag, { cascade: true }) @JoinTable() tags: Tag[]
}

@Injectable()
class RecipesService {
    constructor(@InjectRepository(Recipe) private readonly repo: Repository<Recipe>) {}
    seed() {
        return this.repo.save([
            { title: "Palov", tags: [{ name: "milliy" }, { name: "guruch" }] },
            { title: "Sho'rva", tags: [{ name: "milliy" }] },
            { title: "Mastava", tags: [{ name: "milliy" }, { name: "guruch" }] },
        ] as Recipe[])
    }
    withAllTags(names: string[]) {
        return this.repo.createQueryBuilder("r")
            .innerJoin("r.tags", "t")
            .where("t.name IN (:...names)", { names })
            .groupBy("r.id")
            .having("COUNT(DISTINCT t.name) = :count", { count: names.length })
            .select("r.title", "title")
            .getRawMany()
    }
}

@Controller("recipes")
class RecipesController {
    constructor(private readonly s: RecipesService) {}
    @Get("all-tags") all() { return this.s.withAllTags(["milliy", "guruch"]) }
}

