import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, In, JoinTable, ManyToMany, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Tag { @PrimaryGeneratedColumn() id: number; @Column({ unique: true }) name: string }
@Entity() class Article { @PrimaryGeneratedColumn() id: number; @Column() title: string; @ManyToMany(() => Tag) @JoinTable() tags: Tag[] }

@Injectable() class ArticlesService {
    constructor(@InjectRepository(Article) private readonly articles: Repository<Article>, @InjectRepository(Tag) private readonly tags: Repository<Tag>) {}
    private async resolveTags(names: string[]) {
        const unique = [...new Set(names.map(n => n.trim().toLowerCase()))]
        const existing = await this.tags.findBy({ name: In(unique) })
        const missing = unique.filter(n => !existing.some(t => t.name === n))
        return [...existing, ...(await this.tags.save(missing.map(name => ({ name }))))]
    }
    async create(title: string, tagNames: string[]) { return this.articles.save({ title, tags: await this.resolveTags(tagNames) }) }
    async run() {
        await this.create("Birinchi", ["NestJS", "TypeScript"])
        await this.create("Ikkinchi", ["nestjs", " ORM ", "typescript"])
        console.log("teglar jadvali:", (await this.tags.find({ order: { id: "ASC" } })).map(t => t.name))
    }
}
@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Article, Tag], synchronize: true }), TypeOrmModule.forFeature([Article, Tag])], providers: [ArticlesService] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    await app.get(ArticlesService).run()
    await app.close()
}
main()

import { Controller, Delete, Get, Injectable, Module, Param, ParseIntPipe, Put } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, JoinTable, ManyToMany, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Tag { @PrimaryGeneratedColumn() id: number; @Column() name: string }
@Entity() class Post_ { @PrimaryGeneratedColumn() id: number; @Column() title: string; @ManyToMany(() => Tag) @JoinTable() tags: Tag[] }

@Injectable() class PostTagsService {
    constructor(@InjectRepository(Post_) private readonly posts: Repository<Post_>, @InjectRepository(Tag) private readonly tags: Repository<Tag>, private readonly ds: DataSource) {}
    seed() { return Promise.all([this.tags.save([{ name: "nest" }, { name: "orm" }]), this.posts.save({ title: "P" })]) }
    rel(postId: number) { return this.ds.createQueryBuilder().relation(Post_, "tags").of(postId) }
    async list(postId: number) { return (await this.rel(postId).loadMany<Tag>()).map(t => t.name) }
    async attach(postId: number, tagId: number) { await this.rel(postId).add(tagId); return this.list(postId) }
    async detach(postId: number, tagId: number) { await this.rel(postId).remove(tagId); return this.list(postId) }
}

@Controller("posts/:postId/tags")
class PostTagsController {
    constructor(private readonly s: PostTagsService) {}
    @Get() list(@Param("postId", ParseIntPipe) p: number) { return this.s.list(p) }
    @Put(":tagId") attach(@Param("postId", ParseIntPipe) p: number, @Param("tagId", ParseIntPipe) t: number) { return this.s.attach(p, t) }
    @Delete(":tagId") detach(@Param("postId", ParseIntPipe) p: number, @Param("tagId", ParseIntPipe) t: number) { return this.s.detach(p, t) }
}
@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Post_, Tag], synchronize: true }), TypeOrmModule.forFeature([Post_, Tag])], controllers: [PostTagsController], providers: [PostTagsService] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.app.get(PostTagsService).seed()
    await http.put("/posts/1/tags/1", {})
    await http.put("/posts/1/tags/2", {})
    await http.delete("/posts/1/tags/1")
    await http.close()
}
