import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, JoinTable, ManyToMany, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Tag { @PrimaryGeneratedColumn() id: number; @Column() name: string }
@Entity() class Recipe { @PrimaryGeneratedColumn() id: number; @Column() title: string; @ManyToMany(() => Tag, { cascade: true }) @JoinTable() tags: Tag[] }

@Injectable() class Demo {
    constructor(@InjectRepository(Recipe) private readonly repo: Repository<Recipe>, @InjectRepository(Tag) private readonly tags: Repository<Tag>) {}
    async run() {
        const [milliy, guruch, gosht, shirin] = await this.tags.save([{ name: "milliy" }, { name: "guruch" }, { name: "go'sht" }, { name: "shirin" }])
        await this.repo.save([
            { title: "Palov", tags: [milliy, guruch, gosht] }, { title: "Mastava", tags: [milliy, guruch] },
            { title: "Shashlik", tags: [milliy, gosht] }, { title: "Halvo", tags: [shirin] },
        ])
        const similar = await this.repo.createQueryBuilder("r")
            .innerJoin("r.tags", "t")
            .where("r.id != :id", { id: 1 })
            .andWhere("t.id IN (SELECT tagId FROM recipe_tags_tag WHERE recipeId = :id)", { id: 1 })
            .select("r.title", "title").addSelect("COUNT(t.id)", "common")
            .groupBy("r.id").orderBy("common", "DESC").getRawMany()
        console.log("Palov'ga o'xshashlar:", similar)
    }
}
@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Recipe, Tag], synchronize: true }), TypeOrmModule.forFeature([Recipe, Tag])], providers: [Demo] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    await app.get(Demo).run()
    await app.close()
}
main()

