import { Injectable } from "@nestjs/common"
import assert from "node:assert/strict"

type Group = { id: number; members: number[] }

@Injectable()
class GroupsService {
    constructor(private readonly groups: Map<number, Group>) {}
    join(groupId: number, userId: number) {
        const g = this.groups.get(groupId)!
        if (g.members.includes(userId)) return false
        if (g.members.length >= 3) throw new Error("Guruh to'lgan")
        g.members.push(userId)
        return true
    }
}

const s = new GroupsService(new Map([[1, { id: 1, members: [10, 11] }]]))
assert.equal(s.join(1, 12), true)
assert.equal(s.join(1, 12), false)
assert.throws(() => s.join(1, 13), /to'lgan/)
console.log("✔ qo'shish, takror, to'lgan guruh — tekshirildi")

