import { Injectable, Module, UnprocessableEntityException } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, JoinTable, ManyToMany, PrimaryGeneratedColumn, Relation } from "typeorm"

@Entity() class Student { @PrimaryGeneratedColumn() id: number; @Column() name: string }
@Entity() class Course { @PrimaryGeneratedColumn() id: number; @Column() title: string; @Column() capacity: number; @ManyToMany(() => Student) @JoinTable() students: Relation<Student>[] }

@Injectable()
class EnrollService {
    constructor(private readonly ds: DataSource) {}
    async enroll(courseId: number, studentId: number) {
        const rel = this.ds.createQueryBuilder().relation(Course, "students").of(courseId)
        const course = (await this.ds.getRepository(Course).findOneBy({ id: courseId }))!
        const taken = (await rel.loadMany()).length
        if (taken >= course.capacity) throw new UnprocessableEntityException(`${course.title}: joy qolmadi (${taken}/${course.capacity})`)
        await rel.add(studentId)
        return `${course.title}: ${taken + 1}/${course.capacity}`
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Course, Student], synchronize: true })], providers: [EnrollService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const ds = app.get(DataSource)
    await ds.getRepository(Student).save(["Ali", "Vali", "Soli"].map(name => ({ name })))
    await ds.getRepository(Course).save({ title: "NestJS", capacity: 2 })
    const s = app.get(EnrollService)
    for (const id of [1, 2, 3]) {
        try { console.log("✓", await s.enroll(1, id)) } catch (e) { console.log("✗", (e as Error).message) }
    }
    await app.close()
}
main()

