import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, In, JoinTable, ManyToMany, PrimaryGeneratedColumn, Relation } from "typeorm"

@Entity() class Tag { @PrimaryGeneratedColumn() id: number; @Column({ unique: true }) name: string }
@Entity() class Post { @PrimaryGeneratedColumn() id: number; @Column() title: string; @ManyToMany(() => Tag) @JoinTable() tags: Relation<Tag>[] }

@Injectable()
class PostTagsService {
    constructor(private readonly ds: DataSource) {}
    async sync(postId: number, names: string[]) {
        const rel = this.ds.createQueryBuilder().relation(Post, "tags").of(postId)
        const current = await rel.loadMany<Tag>()
        const wanted = await this.ds.getRepository(Tag).findBy({ name: In(names) })
        const added = wanted.filter(t => !current.some(c => c.id === t.id))
        const removed = current.filter(c => !wanted.some(t => t.id === c.id))
        await rel.addAndRemove(added, removed)
        return { added: added.map(t => t.name), removed: removed.map(t => t.name) }
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Post, Tag], synchronize: true })], providers: [PostTagsService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const ds = app.get(DataSource)
    await ds.getRepository(Tag).save(["milliy", "tez", "go'shtli", "bayram"].map(name => ({ name })))
    await ds.getRepository(Post).save({ title: "Osh" })
    const s = app.get(PostTagsService)
    console.log(await s.sync(1, ["milliy", "go'shtli"]))
    console.log(await s.sync(1, ["milliy", "bayram"]))
    await app.close()
}
main()

