import { Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, JoinTable, ManyToMany, PrimaryGeneratedColumn, Relation } from "typeorm"

@Entity() class Product { @PrimaryGeneratedColumn() id: number; @Column() name: string }
@Entity() class Order { @PrimaryGeneratedColumn() id: number; @ManyToMany(() => Product) @JoinTable({ name: "order_item", joinColumn: { name: "orderId" }, inverseJoinColumn: { name: "productId" } }) items: Relation<Product>[] }

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Order, Product], synchronize: true })] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const ds = app.get(DataSource)
    const [non, choy, shakar, sut] = await ds.getRepository(Product).save(["Non", "Choy", "Shakar", "Sut"].map(name => ({ name })))
    await ds.getRepository(Order).save([{ items: [non, choy, shakar] }, { items: [choy, shakar] }, { items: [non, sut] }, { items: [choy, shakar, sut] }])
    const pairs = await ds.query(`
        SELECT p1.name AS a, p2.name AS b, COUNT(*) AS times
        FROM order_item x JOIN order_item y ON x.orderId = y.orderId AND x.productId < y.productId
        JOIN product p1 ON p1.id = x.productId JOIN product p2 ON p2.id = y.productId
        GROUP BY x.productId, y.productId ORDER BY times DESC, a LIMIT 3`)
    console.table(pairs)
    await app.close()
}
