import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, ManyToOne, PrimaryGeneratedColumn, Relation, Unique } from "typeorm"

@Entity() class User { @PrimaryGeneratedColumn() id: number; @Column() name: string }
@Entity() class Group { @PrimaryGeneratedColumn() id: number; @Column() title: string }
@Entity() @Unique(["user", "group"]) class Membership {
    @PrimaryGeneratedColumn() id: number
    @ManyToOne(() => User) user: Relation<User>
    @ManyToOne(() => Group) group: Relation<Group>
    @Column({ default: "pending" }) status: "pending" | "approved"
    @Column({ default: "member" }) role: "member" | "admin"
}

@Injectable()
class GroupsService {
    constructor(private readonly ds: DataSource) {}
    request(userId: number, groupId: number) { return this.ds.getRepository(Membership).save({ user: { id: userId }, group: { id: groupId } }) }
    approve(id: number) { return this.ds.getRepository(Membership).update(id, { status: "approved" }) }
    members(groupId: number) {
        return this.ds.getRepository(Membership).find({ where: { group: { id: groupId } }, relations: { user: true }, order: { id: "ASC" } })
            .then(ms => ms.map(m => `${m.user.name}: ${m.status}/${m.role}`))
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [User, Group, Membership], synchronize: true })], providers: [GroupsService] })
class AppModule {}

