import { ConflictException, Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, JoinTable, ManyToMany, PrimaryGeneratedColumn, Relation } from "typeorm"

@Entity() class Course { @PrimaryGeneratedColumn() id: number; @Column() title: string; @Column() slot: string }
@Entity() class Student { @PrimaryGeneratedColumn() id: number; @Column() name: string; @ManyToMany(() => Course) @JoinTable() courses: Relation<Course>[] }

@Injectable()
class ScheduleService {
    constructor(private readonly ds: DataSource) {}
    async enroll(studentId: number, courseId: number) {
        const rel = this.ds.createQueryBuilder().relation(Student, "courses").of(studentId)
        const course = (await this.ds.getRepository(Course).findOneBy({ id: courseId }))!
        const clash = (await rel.loadMany<Course>()).find(c => c.slot === course.slot)
        if (clash) throw new ConflictException(`${course.title} (${course.slot}) — ${clash.title} bilan bir vaqtda`)
        await rel.add(courseId)
        return `✓ ${course.title} (${course.slot})`
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Student, Course], synchronize: true })], providers: [ScheduleService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const ds = app.get(DataSource)
    await ds.getRepository(Student).save({ name: "Ali" })
    await ds.getRepository(Course).save([{ title: "NestJS", slot: "Du 10:00" }, { title: "Kotlin", slot: "Du 10:00" }, { title: "SQL", slot: "Se 14:00" }])
    const s = app.get(ScheduleService)
    for (const c of [1, 2, 3]) {
        try { console.log(await s.enroll(1, c)) } catch (e) { console.log("✗", (e as Error).message) }
    }
    await app.close()
}
