import { BadRequestException, Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, JoinTable, ManyToMany, PrimaryGeneratedColumn, Relation } from "typeorm"

@Entity() class Tag { @PrimaryGeneratedColumn() id: number; @Column() name: string }
@Entity() class Post { @PrimaryGeneratedColumn() id: number; @Column() title: string; @ManyToMany(() => Tag) @JoinTable() tags: Relation<Tag>[] }

const MAX_TAGS = 5

@Injectable()
class TagsService {
    constructor(private readonly ds: DataSource) {}
    async add(postId: number, tagIds: number[]) {
        const rel = this.ds.createQueryBuilder().relation(Post, "tags").of(postId)
        const current = (await rel.loadMany<Tag>()).map(t => t.id)
        const fresh = tagIds.filter(id => !current.includes(id))
        if (current.length + fresh.length > MAX_TAGS) throw new BadRequestException(`Ko'pi bilan ${MAX_TAGS} ta teg (hozir ${current.length}, qo'shilmoqchi ${fresh.length})`)
        await rel.add(fresh)
        return current.length + fresh.length
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Post, Tag], synchronize: true })], providers: [TagsService] })
class AppModule {}

