const normalize = (raw: string) => raw.trim().replace(/^#+/, "").toLowerCase().replace(/ +/g, "-")

@Injectable()
class PostsService {
    constructor(private readonly ds: DataSource) {}
    async create(title: string, rawTags: string[]) {
        const names = [...new Set(rawTags.map(normalize).filter(Boolean))]
        await this.ds.getRepository(Tag).upsert(names.map(name => ({ name })), ["name"])
        const tags = await this.ds.getRepository(Tag).findBy({ name: In(names) })
        return this.ds.getRepository(Post).save({ title, tags })
    }
}

