class ManyToMany<A, B> {
    private ab = new Map<A, Set<B>>()
    private ba = new Map<B, Set<A>>()
    link(a: A, b: B) {
        if (!this.ab.has(a)) this.ab.set(a, new Set())
        if (!this.ba.has(b)) this.ba.set(b, new Set())
        this.ab.get(a)!.add(b); this.ba.get(b)!.add(a)
    }
    unlink(a: A, b: B) { this.ab.get(a)?.delete(b); this.ba.get(b)?.delete(a) }
    right(a: A) { return [...(this.ab.get(a) ?? [])] }
    left(b: B) { return [...(this.ba.get(b) ?? [])] }
}

