import { BadRequestException, Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

type Member = { projectId: number; userId: number; role: "admin" | "member" }

@Injectable()
class ProjectMembersService {
    private members: Member[] = [
        { projectId: 1, userId: 1, role: "admin" },
        { projectId: 1, userId: 2, role: "member" },
    ]
    remove(projectId: number, userId: number) {
        const m = this.members.find(x => x.projectId === projectId && x.userId === userId)!
        const admins = this.members.filter(x => x.projectId === projectId && x.role === "admin")
        if (m.role === "admin" && admins.length === 1) throw new BadRequestException("Oxirgi adminni chiqarib bo'lmaydi — avval boshqasini admin qiling")
        this.members = this.members.filter(x => x !== m)
        return this.members.filter(x => x.projectId === projectId).map(x => `${x.userId}:${x.role}`)
    }
    promote(projectId: number, userId: number) { this.members.find(x => x.projectId === projectId && x.userId === userId)!.role = "admin" }
}

@Module({ providers: [ProjectMembersService] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const s = app.get(ProjectMembersService)
    try { s.remove(1, 1) } catch (e) { console.log("✗", (e as Error).message) }
    s.promote(1, 2)
    console.log("✓ qolganlar:", s.remove(1, 1))
    await app.close()
}
