@Entity() class Category {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @Column({ nullable: true }) parentId: number | null
    @ManyToOne(() => Category, c => c.children, { nullable: true, onDelete: "CASCADE" }) parent: Category | null
    @OneToMany(() => Category, c => c.parent) children: Category[]
}

@Injectable() class CategoriesService {
    constructor(@InjectRepository(Category) private repo: Repository<Category>) {}

    create(name: string, parentId?: number) { return this.repo.save({ name, parentId: parentId ?? null }) }

    async tree() {
        const roots = await this.repo.find({
            where: { parentId: IsNull() },
            relations: { children: { children: true } },           // 2 daraja chuqurlikkacha
            order: { id: "ASC" },
        })
        const render = (c: Category, depth = 0): string[] =>
            [`${"  ".repeat(depth)}${c.name}`, ...(c.children ?? []).flatMap(ch => render(ch, depth + 1))]
        return roots.flatMap(r => render(r))
    }
}

