import { Injectable, Module } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, PrimaryGeneratedColumn, Tree, TreeChildren, TreeParent, TreeRepository } from "typeorm"

@Entity()
@Tree("closure-table")
class Comment {
    @PrimaryGeneratedColumn() id: number
    @Column() text: string
    @TreeChildren() replies: Comment[]
    @TreeParent({ onDelete: "CASCADE" }) parent: Comment | null
}

@Injectable() class CommentsService {
    constructor(@InjectRepository(Comment) private repo: TreeRepository<Comment>) {}

    async demo() {
        const root = await this.repo.save({ text: "Maqola zo'r!" })
        const r1 = await this.repo.save({ text: "Qo'shilaman", parent: root })
        const r2 = await this.repo.save({ text: "Menimcha ham", parent: r1 })
        await this.repo.save({ text: "Rahmat!", parent: r2 })
        await this.repo.save({ text: "Boshqa fikr", parent: root })

        const print = (c: Comment, d = 0): void => {
            console.log(`${"  ".repeat(d)}└ ${c.text}`)
            c.replies.forEach(r => print(r, d + 1))
        }
        const [tree] = await this.repo.findTrees()
        print(tree)

        const deepest = await this.repo.findOneByOrFail({ text: "Rahmat!" })
        const ancestors = await this.repo.findAncestors(deepest)
        console.log("Ajdodlar:", ancestors.map(a => a.text).join(" → "))
        console.log("Avlodlar soni (ildizdan):", await this.repo.countDescendants(root) - 1)
    }
}

