    constructor(@InjectRepository(Category) private readonly repo: Repository<Category>) {}
    async seed() {
        const root = await this.repo.save({ name: "Elektronika", parentId: null } as Category)
        const phones = await this.repo.save({ name: "Telefonlar", parentId: root.id } as Category)
