@Entity() class Item {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @Column() path: string
}

@Injectable()
class ItemsService {
    constructor(@InjectRepository(Item) private readonly repo: Repository<Item>) {}
    async move(id: number, newParentPath: string) {
        const item = await this.repo.findOneByOrFail({ id })
        const oldPrefix = `${item.path}${item.id}/`
        const newPrefix = `${newParentPath}${item.id}/`
        item.path = newParentPath
        await this.repo.save(item)
        for (const child of await this.repo.findBy({ path: Like(`${oldPrefix}%`) })) {
            child.path = child.path.replace(oldPrefix, newPrefix)
            await this.repo.save(child)
        }
    }
    async run() {
        await this.repo.save([
            { id: 1, name: "A", path: "/" },
            { id: 2, name: "B", path: "/" },
            { id: 3, name: "A1", path: "/1/" },
            { id: 4, name: "A1x", path: "/1/3/" },
        ] as Item[])
        console.log("oldin:", (await this.repo.find()).map(i => `${i.path}${i.id}:${i.name}`))
        await this.move(3, "/2/")
        console.log("keyin:", (await this.repo.find({ order: { id: "ASC" } })).map(i => `${i.path}${i.id}:${i.name}`))
    }
}

