import { BadRequestException, Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Node_ {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @Column({ type: "int", nullable: true }) parentId: number | null
}

@Injectable()
class TreeService {
    constructor(@InjectRepository(Node_) private readonly repo: Repository<Node_>) {}
    private async isDescendant(candidateId: number, ofId: number) {
        let current = await this.repo.findOneBy({ id: candidateId })
        while (current?.parentId) {
            if (current.parentId === ofId) return true
            current = await this.repo.findOneBy({ id: current.parentId })
        }
        return false
    }
    async move(id: number, newParentId: number) {
        if (id === newParentId) throw new BadRequestException("Element o'ziga ota bo'la olmaydi")
        if (await this.isDescendant(newParentId, id)) throw new BadRequestException("Elementni o'z avlodiga ko'chirib bo'lmaydi")
        await this.repo.update(id, { parentId: newParentId })
        return "ko'chirildi"
    }
    async run() {
        await this.repo.save([
            { id: 1, name: "A", parentId: null },
            { id: 2, name: "B", parentId: 1 },
            { id: 3, name: "C", parentId: 2 },
        ] as Node_[])
