type Node = { name: string; children?: Node[] }

function render(node: Node, prefix = "", isLast = true, isRoot = true): string[] {
    const lines = [isRoot ? node.name : `${prefix}${isLast ? "└── " : "├── "}${node.name}`]
    const kids = node.children ?? []
    kids.forEach((child, i) => lines.push(...render(child, isRoot ? "" : prefix + (isLast ? "    " : "│   "), i === kids.length - 1, false)))
    return lines
}

