type Node = { name: string; children?: Node[] }

function findPath(node: Node, query: string, path: string[] = []): string[][] {
    const here = [...path, node.name]
    const found = node.name.toLowerCase().includes(query.toLowerCase()) ? [here] : []
    return [...found, ...(node.children ?? []).flatMap(c => findPath(c, query, here))]
}

