    constructor(private readonly ds: DataSource) {}
    children(parentId: number) { return this.ds.getRepository(MenuItem).find({ where: { parentId }, order: { sortOrder: "ASC" } }).then(r => r.map(i => i.title)) }
    async moveTo(id: number, newIndex: number) {
        const repo = this.ds.getRepository(MenuItem)
        const item = (await repo.findOneBy({ id }))!
        const list = (await repo.find({ where: { parentId: item.parentId }, order: { sortOrder: "ASC" } })).filter(i => i.id !== id)
