type Flat = { id: number; parentId: number | null; name: string }
type TreeNode = Flat & { children: TreeNode[] }

function buildTree(rows: Flat[]): TreeNode[] {
    const map = new Map<number, TreeNode>()
    for (const r of rows) map.set(r.id, { ...r, children: [] })
    const roots: TreeNode[] = []
    for (const node of map.values()) {
        const parent = node.parentId === null ? undefined : map.get(node.parentId)
        parent ? parent.children.push(node) : roots.push(node)
    }
    return roots
}

