type Row = { id: number; parentId: number | null }

function validate(rows: Row[]) {
    const ids = new Set(rows.map(r => r.id))
    const byId = new Map(rows.map(r => [r.id, r]))
    const problems: string[] = []
    for (const r of rows) if (r.parentId !== null && !ids.has(r.parentId)) problems.push(`#${r.id}: ota #${r.parentId} mavjud emas (yetim)`)
    for (const r of rows) {
        const seen = new Set<number>()
        let cur: Row | undefined = r
        while (cur && cur.parentId !== null) {
            if (seen.has(cur.id)) { problems.push(`#${r.id}: aylanma bog'lanish`); break }
            seen.add(cur.id)
            cur = byId.get(cur.parentId)
        }
    }
    const roots = rows.filter(r => r.parentId === null).length
    if (roots !== 1) problems.push(`ildizlar soni ${roots} (1 bo'lishi kerak)`)
    return problems.length ? problems : ["✓ daraxt to'g'ri"]
}

