type Node = { name: string; children: Node[] }
const n = (name: string, ...children: Node[]): Node => ({ name, children })

const tree = n("Menyu", n("Issiq", n("Osh"), n("Mastava")), n("Salat", n("Vitamin")), n("Choy"))

function dfs(node: Node): string[] { return [node.name, ...node.children.flatMap(dfs)] }
function bfs(root: Node): string[] {
    const out: string[] = []
    const queue = [root]
    while (queue.length) { const cur = queue.shift()!; out.push(cur.name); queue.push(...cur.children) }
    return out
}

