    Kiyim: "Katalog", Futbolka: "Kiyim",
}

function ancestors(node: string): string[] {
    const out: string[] = []
    for (let cur: string | null = node; cur; cur = parent[cur]) out.push(cur)
    return out
}
function lca(a: string, b: string) {
    const up = new Set(ancestors(a))
    return ancestors(b).find(x => up.has(x))
}

