type Node = { name: string; checked?: boolean; children?: Node[] }
type State = "✔" | "✘" | "◐"

function state(node: Node): State {
    if (!node.children?.length) return node.checked ? "✔" : "✘"
    const states = node.children.map(state)
    if (states.every(s => s === "✔")) return "✔"
    if (states.every(s => s === "✘")) return "✘"
    return "◐"
}
function show(node: Node, d = 0): string[] { return [`${"  ".repeat(d)}${state(node)} ${node.name}`, ...(node.children ?? []).flatMap(c => show(c, d + 1))] }

