import {
    Body, CanActivate, ConflictException, Controller, ExecutionContext, Get, Injectable,
    Module, Post, Req, UnauthorizedException, UseGuards,
} from "@nestjs/common"
import { JwtModule, JwtService } from "@nestjs/jwt"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import * as bcrypt from "bcryptjs"
import { Column, Entity, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class User {
    @PrimaryGeneratedColumn() id: number
    @Column({ unique: true }) email: string
    @Column() passwordHash: string
}

@Injectable() class AuthService {
    constructor(@InjectRepository(User) private users: Repository<User>, private jwt: JwtService) {}

    async register(email: string, password: string) {
        if (await this.users.existsBy({ email })) throw new ConflictException("Bu email band")
        const passwordHash = await bcrypt.hash(password, 10)             // 10 — "salt rounds"
        const user = await this.users.save({ email, passwordHash })
        return { id: user.id, email: user.email, hashBoshlanishi: passwordHash.slice(0, 7) }
    }

    async login(email: string, password: string) {
        const user = await this.users.findOneBy({ email })
        const ok = user && (await bcrypt.compare(password, user.passwordHash))
        if (!ok) throw new UnauthorizedException("Email yoki parol noto'g'ri")
        return { accessToken: await this.jwt.signAsync({ sub: user.id, email: user.email }) }
    }
}

@Injectable() class AuthGuard implements CanActivate {
    constructor(private jwt: JwtService) {}
    async canActivate(ctx: ExecutionContext) {
        const req = ctx.switchToHttp().getRequest()
        const [type, token] = (req.headers.authorization ?? "").split(" ")
        if (type !== "Bearer" || !token) throw new UnauthorizedException("Token yo'q")
        try {
            req.user = await this.jwt.verifyAsync(token)
            return true
        } catch {
            throw new UnauthorizedException("Token yaroqsiz")
        }
    }
}

@Controller("auth") class AuthController {
    constructor(private auth: AuthService) {}
    @Post("register") register(@Body() b: { email: string; password: string }) { return this.auth.register(b.email, b.password) }
    @Post("login") login(@Body() b: { email: string; password: string }) { return this.auth.login(b.email, b.password) }

    @Get("me") @UseGuards(AuthGuard)
    me(@Req() req: { user: { sub: number; email: string } }) { return { id: req.user.sub, email: req.user.email } }
}

