import {
    Body, CanActivate, Controller, Delete, ExecutionContext, ForbiddenException, Get, HttpCode, Injectable,
    Module, NotFoundException, Param, ParseIntPipe, Patch, Post, Req, UnauthorizedException, UseGuards,
} from "@nestjs/common"
import { JwtModule, JwtService } from "@nestjs/jwt"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, ManyToOne, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class User { @PrimaryGeneratedColumn() id: number; @Column() name: string }

// Diqqat: entity nomini "Post" qo'ymang — @Post() dekoratori bilan to'qnashadi!
@Entity() class Article {
    @PrimaryGeneratedColumn() id: number
    @Column() title: string
    @Column() ownerId: number
    @ManyToOne(() => User, { onDelete: "CASCADE" }) owner: User
}

type AuthUser = { sub: number }

@Injectable() class AuthGuard implements CanActivate {
    constructor(private jwt: JwtService) {}
    async canActivate(ctx: ExecutionContext) {
        const req = ctx.switchToHttp().getRequest()
        const token = req.headers.authorization?.replace("Bearer ", "")
        try { req.user = await this.jwt.verifyAsync(token) } catch { throw new UnauthorizedException() }
        return true
    }
}

@Injectable() class PostsService {
    constructor(@InjectRepository(Article) private posts: Repository<Article>) {}

    create(ownerId: number, title: string) { return this.posts.save({ ownerId, title }) }
    mine(ownerId: number) { return this.posts.findBy({ ownerId }) }

    private async owned(id: number, userId: number) {
        const post = await this.posts.findOneBy({ id })
        if (!post) throw new NotFoundException("Post topilmadi")
        if (post.ownerId !== userId) throw new ForbiddenException("Bu post sizniki emas")
        return post
    }

    async update(id: number, userId: number, title: string) {
        const post = await this.owned(id, userId)
        post.title = title
        return this.posts.save(post)
    }

    async remove(id: number, userId: number) {
        await this.posts.remove(await this.owned(id, userId))
    }
}

@Controller("posts") @UseGuards(AuthGuard)
class PostsController {
    constructor(private s: PostsService) {}
    @Post() create(@Req() r: { user: AuthUser }, @Body("title") t: string) { return this.s.create(r.user.sub, t) }
    @Get("mine") mine(@Req() r: { user: AuthUser }) { return this.s.mine(r.user.sub) }
    @Patch(":id") update(@Req() r: { user: AuthUser }, @Param("id", ParseIntPipe) id: number, @Body("title") t: string) { return this.s.update(id, r.user.sub, t) }
    @Delete(":id") @HttpCode(204) remove(@Req() r: { user: AuthUser }, @Param("id", ParseIntPipe) id: number) { return this.s.remove(id, r.user.sub) }
}

@Module({
    imports: [
        TypeOrmModule.forRoot({ type: "sqljs", entities: [User, Article], synchronize: true }),
        TypeOrmModule.forFeature([User, Article]),
        JwtModule.register({ secret: "dev-secret" }),
    ],
    controllers: [PostsController], providers: [PostsService, AuthGuard],
})
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.app.get<Repository<User>>("UserRepository").save([{ name: "Ali" }, { name: "Vali" }])
    const jwt = http.app.get(JwtService)
    const ali = { Authorization: `Bearer ${jwt.sign({ sub: 1 })}` }
    const vali = { Authorization: `Bearer ${jwt.sign({ sub: 2 })}` }

    await http.post("/posts", { title: "Ali'ning posti" }, ali)
    await http.post("/posts", { title: "Vali'ning posti" }, vali)
    await http.get("/posts/mine", ali)
    await http.patch("/posts/1", { title: "Buzilgan" }, vali)        // boshqaning posti
    await http.patch("/posts/1", { title: "Tahrirlangan" }, ali)
    await http.delete("/posts/2", ali)
    await http.delete("/posts/2", vali)
    await http.get("/posts/mine", vali)
    await http.get("/posts/mine")                                    // tokensiz
    await http.close()
}
main()

