import { Body, Controller, Injectable, Module, Param, ParseIntPipe, Patch, UnauthorizedException, BadRequestException } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import * as bcrypt from "bcryptjs"
import { Column, Entity, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class User {
    @PrimaryGeneratedColumn() id: number
    @Column() email: string
    @Column() passwordHash: string
}

@Injectable() class AccountService {
    constructor(@InjectRepository(User) private users: Repository<User>) {}

    async seed() {
        await this.users.save({ email: "aziz@mail.uz", passwordHash: await bcrypt.hash("eski-parol", 10) })
    }

    async changePassword(id: number, oldPassword: string, newPassword: string) {
        const user = await this.users.findOneByOrFail({ id })
        if (!(await bcrypt.compare(oldPassword, user.passwordHash))) throw new UnauthorizedException("Joriy parol noto'g'ri")
        if (newPassword.length < 8) throw new BadRequestException("Yangi parol kamida 8 belgi")
        if (await bcrypt.compare(newPassword, user.passwordHash)) throw new BadRequestException("Yangi parol eskisi bilan bir xil")
        user.passwordHash = await bcrypt.hash(newPassword, 10)
        await this.users.save(user)
        return { message: "Parol yangilandi" }
    }
}

@Controller("users") class AccountController {
    constructor(private s: AccountService) {}
    @Patch(":id/password")
    change(@Param("id", ParseIntPipe) id: number, @Body() b: { oldPassword: string; newPassword: string }) {
        return this.s.changePassword(id, b.oldPassword, b.newPassword)
    }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [User], synchronize: true }), TypeOrmModule.forFeature([User])],
    controllers: [AccountController], providers: [AccountService],
})
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.app.get(AccountService).seed()
    await http.patch("/users/1/password", { oldPassword: "xato", newPassword: "yangi-parol-1" })
    await http.patch("/users/1/password", { oldPassword: "eski-parol", newPassword: "123" })
    await http.patch("/users/1/password", { oldPassword: "eski-parol", newPassword: "eski-parol" })
    await http.patch("/users/1/password", { oldPassword: "eski-parol", newPassword: "yangi-parol-1" })
    await http.patch("/users/1/password", { oldPassword: "eski-parol", newPassword: "yana-bir" })
    await http.close()
}
