@Entity() class Review {
    @PrimaryGeneratedColumn() id: number
    @Column() text: string
    @Column() authorId: number
}

type CurrentUser = { id: number; role: "user" | "admin" }

@Injectable() class FakeAuthGuard implements CanActivate {          // soddalik uchun sarlavhadan o'qiymiz
    canActivate(ctx: ExecutionContext) {
        const req = ctx.switchToHttp().getRequest()
        req.user = { id: Number(req.headers["x-user-id"]), role: req.headers["x-role"] ?? "user" }
        return true
    }
}

@Injectable() class ReviewsService {
    constructor(@InjectRepository(Review) private repo: Repository<Review>) {}

    seed() { return this.repo.save([{ text: "Zo'r!", authorId: 1 }, { text: "Yomon", authorId: 2 }, { text: "Spam", authorId: 3 }]) }

    async remove(id: number, user: CurrentUser) {
        const review = await this.repo.findOneBy({ id })
        if (!review) throw new NotFoundException()
        const canDelete = user.role === "admin" || review.authorId === user.id
        if (!canDelete) throw new ForbiddenException("Faqat muallif yoki admin o'chira oladi")
        await this.repo.delete(id)
    }
}

@Controller("reviews") @UseGuards(FakeAuthGuard)
class ReviewsController {
    constructor(private s: ReviewsService) {}
    @Delete(":id") @HttpCode(204)
    remove(@Param("id", ParseIntPipe) id: number, @Req() req: { user: CurrentUser }) { return this.s.remove(id, req.user) }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Review], synchronize: true }), TypeOrmModule.forFeature([Review])],
