import { Column, Entity, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Doc { @PrimaryGeneratedColumn() id: number; @Column() title: string; @Column() ownerId: number }

@Injectable()
class AuthGuard implements CanActivate {
    canActivate(ctx: ExecutionContext) {
        const req = ctx.switchToHttp().getRequest()
        req.user = { id: Number(req.headers["x-user-id"]) }
        return !!req.user.id
    }
}

@Injectable()
class DocsService {
    constructor(@InjectRepository(Doc) private readonly repo: Repository<Doc>) {}
    // 1-usul: 403 — yozuv borligini oshkor qiladi
    async updateStrict(id: number, userId: number, title: string) {
        const doc = await this.repo.findOneBy({ id })
        if (!doc) throw new NotFoundException()
        if (doc.ownerId !== userId) throw new ForbiddenException("Bu hujjat sizniki emas")
        return this.repo.save({ ...doc, title })
    }
    // 2-usul: 404 — begona yozuv "mavjud emas" deb ko'rinadi
    async updateHidden(id: number, userId: number, title: string) {
        const doc = await this.repo.findOneBy({ id, ownerId: userId })
        if (!doc) throw new NotFoundException(`Hujjat #${id} topilmadi`)
        return this.repo.save({ ...doc, title })
    }
}

@Controller("docs")
