class DocsController {
    constructor(private readonly s: DocsService) {}
    @Patch(":id/strict") strict(@Param("id", ParseIntPipe) id: number, @Req() req: any, @Body("title") t: string) { return this.s.updateStrict(id, req.user.id, t) }
    @Patch(":id/hidden") hidden(@Param("id", ParseIntPipe) id: number, @Req() req: any, @Body("title") t: string) { return this.s.updateHidden(id, req.user.id, t) }
}

