import { Body, CanActivate, Controller, ExecutionContext, Get, Injectable, Module, Post, Req, UnauthorizedException, UseGuards } from "@nestjs/common"
import { JwtModule, JwtService } from "@nestjs/jwt"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import * as bcrypt from "bcryptjs"
import { Column, Entity, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class User { @PrimaryGeneratedColumn() id: number; @Column({ unique: true }) email: string; @Column() password: string }
@Entity() class Todo { @PrimaryGeneratedColumn() id: number; @Column() title: string; @Column() userId: number }

@Injectable()
class JwtGuard implements CanActivate {
    constructor(private readonly jwt: JwtService) {}
    async canActivate(ctx: ExecutionContext) {
        const req = ctx.switchToHttp().getRequest()
        const token = req.headers.authorization?.replace("Bearer ", "")
        try { req.user = await this.jwt.verifyAsync(token) } catch { throw new UnauthorizedException("Token yaroqsiz") }
        return true
    }
}

@Controller("auth")
class AuthController {
    constructor(@InjectRepository(User) private readonly users: Repository<User>, private readonly jwt: JwtService) {}
    @Post("register") async register(@Body() b: { email: string; password: string }) {
        const user = await this.users.save({ email: b.email, password: await bcrypt.hash(b.password, 4) })
        return { id: user.id, email: user.email }
    }
    @Post("login") async login(@Body() b: { email: string; password: string }) {
        const user = await this.users.findOneBy({ email: b.email })
        if (!user || !(await bcrypt.compare(b.password, user.password))) throw new UnauthorizedException("Email yoki parol noto'g'ri")
        return { accessToken: await this.jwt.signAsync({ sub: user.id }) }
    }
}

@Controller("todos")
@UseGuards(JwtGuard)
class TodosController {
    constructor(@InjectRepository(Todo) private readonly todos: Repository<Todo>) {}
    @Post() create(@Body("title") title: string, @Req() req: any) { return this.todos.save({ title, userId: req.user.sub }) }
    @Get() mine(@Req() req: any) { return this.todos.findBy({ userId: req.user.sub }) }
}

@Module({
    imports: [
        TypeOrmModule.forRoot({ type: "sqljs", entities: [User, Todo], synchronize: true }), TypeOrmModule.forFeature([User, Todo]),
        JwtModule.register({ secret: "maxfiy", signOptions: { expiresIn: "15m" } }),
    ],
    controllers: [AuthController, TodosController], providers: [JwtGuard],
})
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/auth/register", { email: "ali@mail.uz", password: "sirli123" })
    // tokenni chiqarib o'tirmaymiz — u har safar boshqacha
    const res = await fetch((await http.app.getUrl()) + "/auth/login", {
        method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ email: "ali@mail.uz", password: "sirli123" }),
    })
    const { accessToken } = await res.json()
    console.log(`POST /auth/login → ${res.status} (token olindi: ${accessToken.split(".").length} qismli JWT)`)
    const auth = { Authorization: `Bearer ${accessToken}` }
    await http.post("/todos", { title: "Nest o'rganish" }, auth)
    await http.get("/todos", auth)
    await http.get("/todos", { Authorization: "Bearer soxta" })
    await http.close()
}
main()

