import { CanActivate, Controller, Delete, ExecutionContext, ForbiddenException, Injectable, Module, NotFoundException, Param, ParseIntPipe, UseGuards } from "@nestjs/common"
import { APP_GUARD } from "@nestjs/core"
import { getRepositoryToken, InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Comment { @PrimaryGeneratedColumn() id: number; @Column() text: string; @Column() authorId: number }

@Injectable()
class UserGuard implements CanActivate {
    canActivate(ctx: ExecutionContext) { const r = ctx.switchToHttp().getRequest(); r.user = { id: Number(r.headers["x-user-id"] ?? 0) }; return true }
}

@Injectable()
class CommentOwnerGuard implements CanActivate {
    constructor(@InjectRepository(Comment) private readonly repo: Repository<Comment>) {}
    async canActivate(ctx: ExecutionContext) {
        const req = ctx.switchToHttp().getRequest()
        const comment = await this.repo.findOneBy({ id: Number(req.params.id) })
        if (!comment) throw new NotFoundException("Izoh topilmadi")
        if (comment.authorId !== req.user.id) throw new ForbiddenException("Faqat muallif o'chira oladi")
        return true
    }
}

@Controller("comments")
class CommentsController {
    constructor(@InjectRepository(Comment) private readonly repo: Repository<Comment>) {}
    @Delete(":id")
