import { Injectable, Module, UnauthorizedException } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { JwtModule, JwtService } from "@nestjs/jwt"

@Injectable()
class TokensService {
    private refreshStore = new Map<string, number>()     // refresh token → userId (haqiqiyda: DB'da, xeshlangan)
    constructor(private readonly jwt: JwtService) {}
    async issue(userId: number) {
        const accessToken = await this.jwt.signAsync({ sub: userId }, { expiresIn: "15m" })
        const refreshToken = crypto.randomUUID()
        this.refreshStore.set(refreshToken, userId)
        return { accessToken, refreshToken }
    }
    async rotate(refreshToken: string) {
        const userId = this.refreshStore.get(refreshToken)
        if (!userId) throw new UnauthorizedException("Refresh token yaroqsiz")
        this.refreshStore.delete(refreshToken)            // bir martalik
        return this.issue(userId)
    }
}

@Module({ imports: [JwtModule.register({ secret: "maxfiy" })], providers: [TokensService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const tokens = app.get(TokensService)
    const first = await tokens.issue(1)
    const second = await tokens.rotate(first.refreshToken)
    console.log("yangi juftlik olindi:", second.refreshToken !== first.refreshToken)
    try { await tokens.rotate(first.refreshToken) } catch (e) { console.log("eski refresh qayta ishlatildi:", (e as Error).message) }
    console.log("yangisi ishlaydi:", !!(await tokens.rotate(second.refreshToken)).accessToken)
    await app.close()
}
main()

import { CanActivate, Controller, ExecutionContext, Get, Injectable, Module, Post, Req, UnauthorizedException, UseGuards } from "@nestjs/common"
import { JwtModule, JwtService } from "@nestjs/jwt"

@Injectable()
class Denylist { private ids = new Set<string>(); add(jti: string) { this.ids.add(jti) } has(jti: string) { return this.ids.has(jti) } }

@Injectable()
class JwtGuard implements CanActivate {
    constructor(private readonly jwt: JwtService, private readonly deny: Denylist) {}
    async canActivate(ctx: ExecutionContext) {
        const req = ctx.switchToHttp().getRequest()
        try { req.user = await this.jwt.verifyAsync(req.headers.authorization?.slice(7) ?? "") } catch { throw new UnauthorizedException() }
        if (this.deny.has(req.user.jti)) throw new UnauthorizedException("Token bekor qilingan")
        return true
    }
}

@Controller()
class AuthController {
    constructor(private readonly jwt: JwtService, private readonly deny: Denylist) {}
    @Post("login") async login() { return { token: await this.jwt.signAsync({ sub: 1, jti: crypto.randomUUID() }) } }
    @Get("me") @UseGuards(JwtGuard) me(@Req() req: any) { return { userId: req.user.sub } }
    @Post("logout") @UseGuards(JwtGuard) logout(@Req() req: any) { this.deny.add(req.user.jti); return { ok: true } }
}

@Module({ imports: [JwtModule.register({ secret: "maxfiy", signOptions: { expiresIn: "1h" } })], controllers: [AuthController], providers: [Denylist, JwtGuard] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const { token } = await (await fetch((await http.app.getUrl()) + "/login", { method: "POST" })).json()
    const auth = { Authorization: `Bearer ${token}` }
    await http.get("/me", auth)
    await http.post("/logout", undefined, auth)
    await http.get("/me", auth)
    await http.close()
}
