import { BadRequestException, Body, Controller, Injectable, Module, Post } from "@nestjs/common"
import * as bcrypt from "bcryptjs"
import { createHash, randomBytes } from "node:crypto"

@Injectable()
class ResetService {
    private user = { email: "ali@mail.uz", hash: bcrypt.hashSync("eski", 4) }
    private tokens = new Map<string, { email: string; expires: number }>()   // kalit — tokenning xeshi
    now = () => Date.now()
    private sha = (t: string) => createHash("sha256").update(t).digest("hex")

    request(email: string) {
        if (email !== this.user.email) return { sent: true }     // mavjudligini oshkor qilmaymiz
        const token = randomBytes(24).toString("hex")
        this.tokens.set(this.sha(token), { email, expires: this.now() + 15 * 60_000 })
        return { sent: true, devToken: token }                  // haqiqiyda — faqat emailga
    }
    async reset(token: string, password: string) {
        const entry = this.tokens.get(this.sha(token))
        if (!entry || entry.expires < this.now()) throw new BadRequestException("Token yaroqsiz yoki muddati o'tgan")
        this.tokens.delete(this.sha(token))
        this.user.hash = await bcrypt.hash(password, 4)
        return { changed: true }
    }
}

@Controller("password")
class ResetController {
    constructor(private readonly s: ResetService) {}
    @Post("forgot") forgot(@Body("email") email: string) { return { sent: this.s.request(email).sent } }
    @Post("reset") reset(@Body() b: { token: string; password: string }) { return this.s.reset(b.token, b.password) }
}

@Module({ controllers: [ResetController], providers: [ResetService] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const s = http.app.get(ResetService)
    await http.post("/password/forgot", { email: "yoq@mail.uz" })
    const { devToken } = s.request("ali@mail.uz")
    await http.post("/password/reset", { token: devToken, password: "yangi-parol" })
    await http.post("/password/reset", { token: devToken, password: "yana" })
    const { devToken: late } = s.request("ali@mail.uz")
    s.now = () => Date.now() + 16 * 60_000                       // 16 daqiqa o'tdi
    await http.post("/password/reset", { token: late, password: "kech" })
    await http.close()
}
