import { Body, Controller, HttpCode, HttpException, HttpStatus, Module, Post, UnauthorizedException } from "@nestjs/common"

const attempts = new Map<string, number>()
const LIMIT = 5

@Controller("auth")
class AuthController {
    @Post("login")
    @HttpCode(200)
    login(@Body() b: { email: string; password: string }) {
        const n = attempts.get(b.email) ?? 0
        if (n >= LIMIT) throw new HttpException("Juda ko'p urinish — 15 daqiqadan keyin qayta urinib ko'ring", HttpStatus.TOO_MANY_REQUESTS)
        if (b.password !== "to'g'ri-parol") {
            attempts.set(b.email, n + 1)
            throw new UnauthorizedException(`Email yoki parol noto'g'ri (qoldi: ${LIMIT - n - 1})`)
