import { CanActivate, Controller, ExecutionContext, Get, Injectable, Module, Post, UnauthorizedException, UseGuards } from "@nestjs/common"
import { JwtModule, JwtService } from "@nestjs/jwt"

const user = { id: 1, tokenVersion: 1 }

@Injectable()
class VersionGuard implements CanActivate {
    constructor(private readonly jwt: JwtService) {}
    canActivate(ctx: ExecutionContext) {
        const { sub, ver } = this.jwt.verify(ctx.switchToHttp().getRequest().headers.authorization.slice(7))
        if (sub !== user.id || ver !== user.tokenVersion) throw new UnauthorizedException("Sessiya bekor qilingan — qayta kiring")
        return true
    }
}

@Controller()
