    @Get("me") @UseGuards(VersionGuard) me() { return { id: user.id } }
    @Post("password") changePassword() { user.tokenVersion++; return { changed: true } }
}

@Module({ imports: [JwtModule.register({ secret: "s3cret" })], controllers: [AccountController], providers: [VersionGuard] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const jwt = http.app.get(JwtService)
    const old = { Authorization: `Bearer ${jwt.sign({ sub: 1, ver: user.tokenVersion })}` }
    await http.get("/me", old)
    await http.post("/password")
    await http.get("/me", old)
    await http.get("/me", { Authorization: `Bearer ${jwt.sign({ sub: 1, ver: user.tokenVersion })}` })
    await http.close()
}
