import { createHash, timingSafeEqual } from "node:crypto"

const sha = (s: string) => createHash("sha256").update(s).digest()
// bazada kalitning o'zi emas, hash'i saqlanadi
const keys = [{ client: "partner-shop", hash: sha("pk_live_abc123") }]

@Injectable()
class ApiKeyGuard implements CanActivate {
    canActivate(ctx: ExecutionContext) {
        const req = ctx.switchToHttp().getRequest()
        const given = sha(String(req.headers["x-api-key"] ?? ""))
        const match = keys.find(k => timingSafeEqual(k.hash, given))
        if (!match) throw new UnauthorizedException("API kalit noto'g'ri")
        req.client = match.client
        return true
    }
}

