type User = { id: number; role: "admin" | "author" | "reader" }
type Post = { ownerId: number; published: boolean }
type Action = "read" | "update" | "delete" | "publish"

function can(user: User, action: Action, post: Post): boolean {
    if (user.role === "admin") return true
    const own = post.ownerId === user.id
    switch (action) {
        case "read": return post.published || own
        case "update": return own && user.role === "author"
        case "publish": return own && user.role === "author" && !post.published
        case "delete": return own && !post.published
    }
}

const post: Post = { ownerId: 2, published: false }
const users: User[] = [{ id: 1, role: "admin" }, { id: 2, role: "author" }, { id: 3, role: "reader" }]
console.table(users.map(u => ({ user: `${u.role}#${u.id}`, ...Object.fromEntries((["read", "update", "publish", "delete"] as Action[]).map(a => [a, can(u, a, post) ? "✓" : "—"])) })))

