import { BadRequestException, Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import * as bcrypt from "bcryptjs"

@Injectable()
class PasswordService {
    private history: string[] = []
    async change(newPassword: string) {
        for (const old of this.history) {
            if (await bcrypt.compare(newPassword, old)) throw new BadRequestException("Bu parol yaqinda ishlatilgan — boshqasini tanlang")
        }
        this.history = [await bcrypt.hash(newPassword, 4), ...this.history].slice(0, 3)
        return `✓ o'zgardi (tarixda ${this.history.length} ta)`
    }
}

