import { CanActivate, Controller, Delete, ExecutionContext, ForbiddenException, Get, Injectable, Module, UseGuards } from "@nestjs/common"
import { Reflector } from "@nestjs/core"

const RequirePermissions = Reflector.createDecorator<string[]>()
const rolePermissions: Record<string, string[]> = {
    moderator: ["comment.read", "comment.delete"],
    support: ["comment.read"],
}

@Injectable()
class PermissionsGuard implements CanActivate {
    constructor(private readonly reflector: Reflector) {}
    canActivate(ctx: ExecutionContext) {
        const needed = this.reflector.get(RequirePermissions, ctx.getHandler()) ?? []
        const role = ctx.switchToHttp().getRequest().headers["x-role"]
        const has = new Set(rolePermissions[role] ?? [])
        const missing = needed.filter(p => !has.has(p))
        if (missing.length) throw new ForbiddenException(`Yetishmayotgan ruxsat: ${missing.join(", ")}`)
        return true
    }
}

@Controller("comments") @UseGuards(PermissionsGuard)
class CommentsController {
    @RequirePermissions(["comment.read"]) @Get() list() { return ["zo'r!", "spam"] }
