import { CanActivate, Controller, ExecutionContext, Get, Injectable, Module, UnauthorizedException, UseGuards } from "@nestjs/common"

@Injectable()
class BearerGuard implements CanActivate {
    canActivate(ctx: ExecutionContext) {
        const header: string | undefined = ctx.switchToHttp().getRequest().headers.authorization
        if (!header) throw new UnauthorizedException("Authorization sarlavhasi yo'q")
        const [scheme, token] = header.split(" ")
        if (scheme !== "Bearer" || !token) throw new UnauthorizedException("Format: Authorization: Bearer <token>")
        return true
    }
}

@Controller("me") @UseGuards(BearerGuard)
class MeController { @Get() me() { return { ok: true } } }

