import { CanActivate, Controller, ExecutionContext, Get, HttpCode, Injectable, Module, Post, Res, UnauthorizedException, UseGuards } from "@nestjs/common"
import { JwtModule, JwtService } from "@nestjs/jwt"

@Injectable()
class CookieAuthGuard implements CanActivate {
    constructor(private readonly jwt: JwtService) {}
    canActivate(ctx: ExecutionContext) {
        const req = ctx.switchToHttp().getRequest()
        const token = /(?:^|; )access=([^;]+)/.exec(req.headers.cookie ?? "")?.[1]
        if (!token) throw new UnauthorizedException("Cookie yo'q")
        req.user = this.jwt.verify(token)
        return true
    }
}

@Controller("auth")
class AuthController {
    constructor(private readonly jwt: JwtService) {}
    @Post("login") @HttpCode(204)
    login(@Res({ passthrough: true }) res: { cookie(n: string, v: string, o: object): void }) {
        res.cookie("access", this.jwt.sign({ sub: 7 }), { httpOnly: true, sameSite: "lax", secure: true, path: "/" })
    }
    @Get("me") @UseGuards(CookieAuthGuard) me() { return { sub: 7 } }
}

