import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

type Cart = Map<string, number>

@Injectable()
class CartService {
    private guest = new Map<string, Cart>([["guest-abc", new Map([["non", 2], ["choy", 1]])]])
    private users = new Map<number, Cart>([[7, new Map([["non", 1], ["shakar", 1]])]])

    mergeOnLogin(guestId: string, userId: number) {
        const from = this.guest.get(guestId) ?? new Map()
        const to = this.users.get(userId) ?? new Map()
        for (const [item, qty] of from) to.set(item, (to.get(item) ?? 0) + qty)
        this.users.set(userId, to)
        this.guest.delete(guestId)
        return Object.fromEntries(to)
    }
}

