import { Body, Controller, ForbiddenException, Headers, Module, Param, ParseIntPipe, Patch } from "@nestjs/common"

let NOW = Date.parse("2025-05-01T10:00:00Z")
const comments = [{ id: 1, ownerId: 7, text: "Zo'r!", createdAt: Date.parse("2025-05-01T09:50:00Z") }]
const EDIT_WINDOW_MS = 15 * 60_000

@Controller("comments")
class CommentsController {
    @Patch(":id")
    edit(@Param("id", ParseIntPipe) id: number, @Headers("x-user-id") uid: string, @Body("text") text: string) {
        const c = comments.find(x => x.id === id)!
        if (c.ownerId !== Number(uid)) throw new ForbiddenException("Faqat muallif tahrirlay oladi")
        const left = EDIT_WINDOW_MS - (NOW - c.createdAt)
        if (left <= 0) throw new ForbiddenException("Tahrirlash vaqti tugagan (15 daqiqa)")
        c.text = text
        return { text, minutesLeft: Math.floor(left / 60_000) }
    }
}

