import { BadRequestException, Body, Controller, Get, HttpCode, Module, Post, Query } from "@nestjs/common"
import { JwtModule, JwtService } from "@nestjs/jwt"

const used = new Set<string>()
const outbox: string[] = []

@Controller("auth/magic")
class MagicController {
    constructor(private readonly jwt: JwtService) {}

    @Post() @HttpCode(202)
    send(@Body("email") email: string) {
        const token = this.jwt.sign({ email, jti: `m-${outbox.length + 1}` }, { expiresIn: "10m" })
        outbox.push(`/auth/magic?token=${token}`)
        return { sent: true }
    }

    @Get()
    login(@Query("token") token: string) {
        const p = this.jwt.verify(token)
        if (used.has(p.jti)) throw new BadRequestException("Havola allaqachon ishlatilgan")
        used.add(p.jti)
        return { loggedIn: p.email }
    }
}

@Module({ imports: [JwtModule.register({ secret: "s3cret" })], controllers: [MagicController] })
class AppModule {}

