    await http.post("/auth/magic", { email: "ali@mail.uz" })
    const link = outbox[0]
    for (let i = 0; i < 2; i++) {
        const r = await fetch((await http.app.getUrl()) + link)
        console.log(`${i + 1}-bosish →`, r.status, JSON.stringify(await r.json()))
    }
    await http.close()
}
