import { Controller, Delete, Get, HttpCode, Injectable, Module, NotFoundException, Param, ParseIntPipe, Patch, Query } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, DeleteDateColumn, Entity, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Customer {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @DeleteDateColumn() deletedAt: Date | null
}

@Injectable() class CustomersService {
    constructor(@InjectRepository(Customer) private repo: Repository<Customer>) {}

    seed() { return this.repo.save([{ name: "Ali" }, { name: "Vali" }, { name: "Hasan" }]) }

    async list(withDeleted: boolean) {
        const list = await this.repo.find({ withDeleted, order: { id: "ASC" } })
        return list.map(c => `${c.name}${c.deletedAt ? " (o'chirilgan)" : ""}`)
    }

    async softDelete(id: number) {
        const res = await this.repo.softDelete(id)
        if (!res.affected) throw new NotFoundException()
    }

    async restore(id: number) {
        const res = await this.repo.restore(id)
        if (!res.affected) throw new NotFoundException()
        return this.repo.findOneBy({ id }).then(c => ({ restored: c!.name }))
    }
}

@Controller("customers") class CustomersController {
    constructor(private s: CustomersService) {}
    @Get() list(@Query("withDeleted") w?: string) { return this.s.list(w === "true") }
    @Delete(":id") @HttpCode(204) remove(@Param("id", ParseIntPipe) id: number) { return this.s.softDelete(id) }
    @Patch(":id/restore") restore(@Param("id", ParseIntPipe) id: number) { return this.s.restore(id) }
}

@Module({
