import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, DeleteDateColumn, Entity, LessThan, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Note {
    @PrimaryGeneratedColumn() id: number
    @Column() title: string
    @DeleteDateColumn() deletedAt: Date | null
}

@Injectable()
class CleanupService {
    constructor(@InjectRepository(Note) private readonly repo: Repository<Note>) {}
    purgeOlderThan(days: number) {
        const limit = new Date(Date.now() - days * 24 * 60 * 60 * 1000)
        return this.repo.delete({ deletedAt: LessThan(limit) })   // hard delete
    }
    async run() {
        await this.repo.save([{ title: "eski" }, { title: "yangi" }, { title: "faol" }] as Note[])
        await this.repo.softDelete([1, 2])
        // "eski"ni 40 kun oldin o'chirilgan qilib ko'rsatamiz
        await this.repo.update({ id: 1 }, { deletedAt: new Date(Date.now() - 40 * 864e5) })

        console.log("arxivda:", await this.repo.count({ withDeleted: true }))
        const res = await this.purgeOlderThan(30)
        console.log("butunlay o'chirildi:", res.affected)
        console.log("qoldi:", (await this.repo.find({ withDeleted: true })).map(n => n.title))
    }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Note], synchronize: true }), TypeOrmModule.forFeature([Note])],
