import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, UseInterceptors } from "@nestjs/common"
import { getRepositoryToken, InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { map, Observable } from "rxjs"
import { Column, DeleteDateColumn, Entity, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Note {
    @PrimaryGeneratedColumn() id: number
    @Column() title: string
    @DeleteDateColumn() deletedAt: Date | null
}

@Injectable()
class StripDeletedAtInterceptor implements NestInterceptor {
    intercept(_ctx: ExecutionContext, next: CallHandler): Observable<unknown> {
        const strip = (v: any) => { if (v && typeof v === "object") delete v.deletedAt; return v }
        return next.handle().pipe(map(data => Array.isArray(data) ? data.map(strip) : strip(data)))
    }
}

@Controller("notes")
@UseInterceptors(StripDeletedAtInterceptor)
class NotesController {
    constructor(@InjectRepository(Note) private readonly repo: Repository<Note>) {}
    @Get() all() { return this.repo.find() }
}

