import { ConflictException, Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, DeleteDateColumn, Entity, PrimaryGeneratedColumn } from "typeorm"

@Entity() class Category { @PrimaryGeneratedColumn() id: number; @Column() name: string; @DeleteDateColumn() deletedAt: Date | null }

@Injectable()
class CategoriesService {
    constructor(private readonly ds: DataSource) {}
    async restore(id: number) {
        const repo = this.ds.getRepository(Category)
        const item = (await repo.findOne({ where: { id }, withDeleted: true }))!
        if (await repo.findOneBy({ name: item.name })) throw new ConflictException(`"${item.name}" nomli faol kategoriya bor — avval uni qayta nomlang`)
        await repo.restore(id)
        return `✓ tiklandi: ${item.name}`
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Category], synchronize: true })], providers: [CategoriesService] })
