import { GoneException, Injectable, Module, NotFoundException } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, DeleteDateColumn, Entity, PrimaryGeneratedColumn } from "typeorm"

@Entity() class File { @PrimaryGeneratedColumn() id: number; @Column() name: string; @DeleteDateColumn() deletedAt: Date | null }

const NOW = new Date("2025-05-20T12:00:00Z")
const WINDOW_DAYS = 7

@Injectable()
class FilesService {
    constructor(private readonly ds: DataSource) {}
    async restore(id: number) {
        const repo = this.ds.getRepository(File)
        const f = await repo.findOne({ where: { id }, withDeleted: true })
        if (!f?.deletedAt) throw new NotFoundException()
        const days = (NOW.getTime() - f.deletedAt.getTime()) / 86_400_000
        if (days > WINDOW_DAYS) throw new GoneException(`${f.name}: ${Math.floor(days)} kun o'tgan, tiklash muddati ${WINDOW_DAYS} kun`)
        await repo.restore(id)
        return `✓ ${f.name} tiklandi`
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [File], synchronize: true })], providers: [FilesService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    await app.get(DataSource).getRepository(File).save([
        { name: "menyu.pdf", deletedAt: new Date("2025-05-18") }, { name: "eski.pdf", deletedAt: new Date("2025-05-01") },
    ])
    const s = app.get(FilesService)
    for (const id of [1, 2]) {
        try { console.log(await s.restore(id)) } catch (e) { console.log("✗", (e as GoneException).getStatus(), (e as Error).message) }
    }
    await app.close()
}
main()

