class SoftRepo<T extends { id: number }> {
    private rows: (T & { deletedAt: Date | null })[] = []
    insert(row: T) { this.rows.push({ ...row, deletedAt: null }) }
    find(opts: { withDeleted?: boolean } = {}) { return this.rows.filter(r => opts.withDeleted || !r.deletedAt).map(r => r.id) }
    softDelete(id: number, at = new Date("2025-05-01")) { const r = this.rows.find(x => x.id === id && !x.deletedAt); if (r) r.deletedAt = at; return !!r }
    restore(id: number) { const r = this.rows.find(x => x.id === id && x.deletedAt); if (r) r.deletedAt = null; return !!r }
    purge() { const before = this.rows.length; this.rows = this.rows.filter(r => !r.deletedAt); return before - this.rows.length }
}

const repo = new SoftRepo<{ id: number; name: string }>()
;[1, 2, 3].forEach(id => repo.insert({ id, name: `taom-${id}` }))
console.log("softDelete(2):", repo.softDelete(2), "| softDelete(2) yana:", repo.softDelete(2))
console.log("faol:", repo.find(), "| hammasi:", repo.find({ withDeleted: true }))
repo.softDelete(3)
console.log("restore(2):", repo.restore(2), "| purge:", repo.purge(), "| qoldi:", repo.find({ withDeleted: true }))

