import { BadRequestException, Body, Controller, Get, Injectable, Module, Post } from "@nestjs/common"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, PrimaryGeneratedColumn } from "typeorm"

@Entity() class Product {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @Column("int") stock: number
}

@Entity() class Order {
    @PrimaryGeneratedColumn() id: number
    @Column() productId: number
    @Column("int") qty: number
}

@Injectable() class CheckoutService {
    constructor(private dataSource: DataSource) {}

    seed() { return this.dataSource.getRepository(Product).save({ name: "Noutbuk", stock: 3 }) }

    placeOrder(productId: number, qty: number) {
        return this.dataSource.transaction(async manager => {
            const order = await manager.save(Order, { productId, qty })        // 1-qadam: buyurtma yaratildi
            const product = await manager.findOneByOrFail(Product, { id: productId })
            if (product.stock < qty) {
                throw new BadRequestException(`Omborda faqat ${product.stock} ta bor`)   // → ROLLBACK: buyurtma ham bekor
            }
            product.stock -= qty                                                // 2-qadam: qoldiq kamaydi
            await manager.save(product)
            return { orderId: order.id, stockLeft: product.stock }
        })
    }

    async state() {
        return {
            orders: await this.dataSource.getRepository(Order).count(),
            stock: (await this.dataSource.getRepository(Product).findOneByOrFail({ id: 1 })).stock,
        }
    }
}

@Controller() class CheckoutController {
    constructor(private s: CheckoutService) {}
    @Post("orders") order(@Body() b: { productId: number; qty: number }) { return this.s.placeOrder(b.productId, b.qty) }
    @Get("state") state() { return this.s.state() }
}

