@Injectable() class TransferService {
    constructor(private dataSource: DataSource) {}

    seed() { return this.dataSource.getRepository(Wallet).save([{ owner: "Ali", balance: 100_000 }, { owner: "Vali", balance: 20_000 }]) }

    transfer(fromId: number, toId: number, amount: number) {
        return this.dataSource.transaction(async manager => {
            await manager.decrement(Wallet, { id: fromId }, "balance", amount)
            const from = await manager.findOneByOrFail(Wallet, { id: fromId })
            if (from.balance < 0) throw new BadRequestException("Mablag' yetarli emas")

            const to = await manager.findOneBy(Wallet, { id: toId })
            if (!to) throw new NotFoundException("Qabul qiluvchi hisob topilmadi")   // yechilgan pul qaytadi
            await manager.increment(Wallet, { id: toId }, "balance", amount)
            return { ok: true }
        })
    }

    async balances() {
        const list = await this.dataSource.getRepository(Wallet).find({ order: { id: "ASC" } })
        return list.map(w => `${w.owner}: ${w.balance}`)
    }
}

