    constructor(@InjectRepository(Account) private readonly repo: Repository<Account>, private readonly ds: DataSource) {}
    seed() { return this.repo.save([{ owner: "Ali", balance: 100_000 }, { owner: "Laylo", balance: 50_000 }] as Account[]) }
    all() { return this.repo.find({ order: { id: "ASC" } }) }

