            from.balance -= amount
            await manager.save(from)                       // birinchi yozuv
            if (from.balance < 0) throw new BadRequestException("Mablag' yetarli emas")
            to.balance += amount
            await manager.save(to)
            return { from: from.balance, to: to.balance }
        })
    }
}

