    async reserve(id: number, qty: number) {
        const runner = this.ds.createQueryRunner()
        await runner.connect()
        await runner.startTransaction()
        try {
            const product = await runner.manager.findOneByOrFail(Product, { id })
            if (product.stock < qty) throw new Error(`Omborda faqat ${product.stock} dona bor`)
            product.stock -= qty
            await runner.manager.save(product)
            await runner.commitTransaction()
            return "band qilindi"
        } catch (e) {
            await runner.rollbackTransaction()
            return `bekor qilindi: ${(e as Error).message}`
        } finally {
            await runner.release()   // ulanishni qaytarish — majburiy
        }
    }
    async run() {
        await this.repo.save({ name: "Noutbuk", stock: 5 } as Product)
