        @InjectRepository(OrderLine) private readonly lines: Repository<OrderLine>,
        private readonly ds: DataSource,
    ) {}
    place(customer: string, items: { productId: number; qty: number }[]) {
        return this.ds.transaction(async m => {
            const order = await m.save(Order, { customer })
            for (const item of items) {
                const product = await m.findOneByOrFail(Product, { id: item.productId })
                if (product.stock < item.qty) throw new Error(`${product.name}: omborda yetarli emas`)
                await m.decrement(Product, { id: product.id }, "stock", item.qty)
                await m.save(OrderLine, { orderId: order.id, ...item })
            }
            return order.id
        })
    }
    async run() {
        await this.products.save([{ name: "Choy", stock: 10 }, { name: "Non", stock: 2 }] as Product[])

        console.log("1-buyurtma id:", await this.place("Ali", [{ productId: 1, qty: 2 }]))
        try { await this.place("Vali", [{ productId: 1, qty: 1 }, { productId: 2, qty: 5 }]) }
        catch (e) { console.log("2-buyurtma xato:", (e as Error).message) }

        console.log("buyurtmalar:", await this.orders.count(), "| qatorlar:", await this.lines.count())
        console.log("qoldiqlar:", (await this.products.find()).map(p => `${p.name}:${p.stock}`))
    }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Product, Order, OrderLine], synchronize: true }), TypeOrmModule.forFeature([Product, Order, OrderLine])],
    providers: [OrdersService],
})
class AppModule {}

