import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, OptimisticLockVersionMismatchError, PrimaryGeneratedColumn, Repository, VersionColumn } from "typeorm"

@Entity() class Document {
    @PrimaryGeneratedColumn() id: number
    @Column() text: string
    @VersionColumn() version: number
}

@Injectable()
class Demo {
    constructor(@InjectRepository(Document) private readonly repo: Repository<Document>) {}
    async run() {
        const doc = await this.repo.save({ text: "v1" } as Document)
        console.log("boshlang'ich versiya:", doc.version)

        // ikki foydalanuvchi bir xil versiyani o'qidi
        const userA = await this.repo.findOneByOrFail({ id: doc.id })
        const userB = await this.repo.findOneByOrFail({ id: doc.id })

        userA.text = "A o'zgartirdi"
        await this.repo.save(userA)
        console.log("A saqladi, yangi versiya:", (await this.repo.findOneByOrFail({ id: doc.id })).version)

        try {
            userB.text = "B o'zgartirdi"
            await this.repo.update({ id: doc.id, version: userB.version }, { text: userB.text })
            const fresh = await this.repo.findOneByOrFail({ id: doc.id })
            console.log("B'ning yangilanishi qo'llanildimi:", fresh.text === "B o'zgartirdi")
        } catch (e) {
            console.log("konflikt:", e instanceof OptimisticLockVersionMismatchError)
        }
        console.log("yakuniy matn:", (await this.repo.findOneByOrFail({ id: doc.id })).text)
    }
}

