import { CallHandler, Controller, createParamDecorator, ExecutionContext, Injectable, Module, NestInterceptor, Post, UseInterceptors } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { catchError, concatMap, from, Observable, switchMap } from "rxjs"
import { Column, DataSource, Entity, EntityManager, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Row { @PrimaryGeneratedColumn() id: number; @Column() text: string }

// Handler'ga tranzaksiya ichidagi manager'ni beradigan dekorator
const TxManager = createParamDecorator((_: unknown, ctx: ExecutionContext): EntityManager => ctx.switchToHttp().getRequest().txManager)

@Injectable()
class TransactionInterceptor implements NestInterceptor {
    constructor(private readonly ds: DataSource) {}
    intercept(ctx: ExecutionContext, next: CallHandler): Observable<unknown> {
        const runner = this.ds.createQueryRunner()
        return from(runner.connect().then(() => runner.startTransaction())).pipe(
            switchMap(() => {
                ctx.switchToHttp().getRequest().txManager = runner.manager
                return next.handle()
            }),
            concatMap(async data => { await runner.commitTransaction(); await runner.release(); return data }),
            catchError(async err => { await runner.rollbackTransaction(); await runner.release(); throw err }),
        )
    }
}

@Controller("rows")
@UseInterceptors(TransactionInterceptor)
class RowsController {
    @Post("ok") async ok(@TxManager() m: EntityManager) {
        await m.save(Row, [{ text: "a" }, { text: "b" }])
        return { saved: 2 }
    }
    @Post("fail") async fail(@TxManager() m: EntityManager) {
        await m.save(Row, { text: "yo'qolishi kerak" })
        throw new Error("handler ichida xato")
    }
}

@Controller("stats")
class StatsController {
    constructor(@InjectRepository(Row) private readonly repo: Repository<Row>) {}
    @Post() async count() { return { rows: (await this.repo.find()).map(r => r.text) } }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Row], synchronize: true }), TypeOrmModule.forFeature([Row])],
    controllers: [RowsController, StatsController],
})
