import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { InjectModel, MongooseModule, Prop, Schema, SchemaFactory } from "@nestjs/mongoose"
import { Model } from "mongoose"

@Schema({ versionKey: false }) class Account { @Prop() owner: string; @Prop() balance: number }
const AccountSchema = SchemaFactory.createForClass(Account)

@Injectable()
class BankService {
    constructor(@InjectModel("Account") private readonly model: Model<Account>) {}
    async transfer(from: string, to: string, amount: number) {
        const session = await this.model.db.startSession()
        try {
            await session.withTransaction(async () => {
                await this.model.updateOne({ owner: from }, { $inc: { balance: -amount } }, { session })
                await this.model.updateOne({ owner: to }, { $inc: { balance: amount } }, { session })
            })
            return "o'tkazildi"
        } finally {
            await session.endSession()
        }
    }
    async run() {
        await this.model.create([{ owner: "Ali", balance: 100 }, { owner: "Laylo", balance: 50 }])
        try {
            console.log(await this.transfer("Ali", "Laylo", 30))
        } catch (e) {
            // bu misol yakka (standalone) MongoDB serverida ishga tushirildi
            console.log("xato:", (e as Error).message)
        }
        console.log("Yechim: replica set (masalan, MongoMemoryReplSet yoki Atlas) ishlatish")
    }
}

@Module({
    imports: [
        MongooseModule.forRootAsync({ useFactory: async () => ({ uri: await startMongo() }) }),
        MongooseModule.forFeature([{ name: "Account", schema: AccountSchema }]),
    ],
    providers: [BankService],
})
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    await app.get(BankService).run()
    await app.close()
    await stopMongo()
}
main()

