import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, PrimaryGeneratedColumn } from "typeorm"

@Entity() class Order { @PrimaryGeneratedColumn() id: number; @Column() total: number }
@Entity() class Outbox { @PrimaryGeneratedColumn() id: number; @Column() type: string; @Column("simple-json") payload: object; @Column({ default: false }) sent: boolean }

@Injectable()
class OrdersService {
    constructor(private readonly ds: DataSource) {}
    create(total: number) {
        return this.ds.transaction(async em => {
            const order = await em.save(Order, { total })
            await em.save(Outbox, { type: "order.created", payload: { id: order.id, total } })
            return order.id
        })
    }
    async relay(publish: (type: string, payload: object) => void) {
        const pending = await this.ds.getRepository(Outbox).findBy({ sent: false })
        for (const m of pending) { publish(m.type, m.payload); await this.ds.getRepository(Outbox).update(m.id, { sent: true }) }
        return pending.length
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Order, Outbox], synchronize: true })], providers: [OrdersService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const s = app.get(OrdersService)
    await s.create(50000); await s.create(18000)
    const sent = await s.relay((type, p) => console.log("  → broker:", type, JSON.stringify(p)))
    console.log("yuborildi:", sent, "| ikkinchi relay:", await s.relay(() => {}))
    await app.close()
}
