import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, EntityManager, PrimaryGeneratedColumn } from "typeorm"

@Entity() class Booking { @PrimaryGeneratedColumn() id: number; @Column() seat: string }
class TransientError extends Error {}

@Injectable()
class BookingService {
    attempts = 0
    constructor(private readonly ds: DataSource) {}
    private async withRetry<T>(work: (em: EntityManager) => Promise<T>, max = 3): Promise<T> {
        for (let i = 1; ; i++) {
            try { return await this.ds.transaction(work) }
            catch (e) { if (!(e instanceof TransientError) || i === max) throw e; console.log(`  ${i}-urinish bekor qilindi, qayta...`) }
        }
    }
    book(seat: string) {
        return this.withRetry(async em => {
            this.attempts++
            await em.save(Booking, { seat })
            if (this.attempts < 3) throw new TransientError("baza band")
            return seat
        })
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Booking], synchronize: true })], providers: [BookingService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const s = app.get(BookingService)
    console.log("band qilindi:", await s.book("12A"), "| bazadagi yozuvlar:", await app.get(DataSource).getRepository(Booking).count())
    await app.close()
}
