import { Column, DataSource, Entity, PrimaryGeneratedColumn } from "typeorm"

@Entity() class Wallet { @PrimaryGeneratedColumn() id: number; @Column() balance: number }

@Injectable()
class WalletService {
    constructor(private readonly ds: DataSource) {}
    async withdraw(id: number, amount: number) {
        const res = await this.ds.getRepository(Wallet).createQueryBuilder().update()
            .set({ balance: () => "balance - :amount" }).where("id = :id AND balance >= :amount", { id, amount }).execute()
        if (!res.affected) throw new BadRequestException(`${amount} yechib bo'lmaydi — mablag' yetarli emas`)
        return (await this.ds.getRepository(Wallet).findOneBy({ id }))!.balance
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Wallet], synchronize: true })], providers: [WalletService] })
