    await app.get(DataSource).getRepository(Wallet).save({ balance: 100000 })
    const s = app.get(WalletService)
    const results = await Promise.allSettled([s.withdraw(1, 60000), s.withdraw(1, 60000)])
    console.log(results.map(r => (r.status === "fulfilled" ? `✓ qoldi ${r.value}` : `✗ ${(r.reason as Error).message}`)))
    await app.close()
}
