@Entity() class Counter { @PrimaryColumn() key: string; @Column() value: number }
@Entity() class Invoice { @PrimaryGeneratedColumn() id: number; @Column() number: string; @Column() amount: number }

@Injectable()
class InvoicesService {
    constructor(private readonly ds: DataSource) {}
    create(year: number, amount: number, fail = false) {
        return this.ds.transaction(async em => {
            const key = `invoice-${year}`
            await em.query("INSERT INTO counter (key, value) VALUES (?, 1) ON CONFLICT(key) DO UPDATE SET value = value + 1", [key])
            const { value } = await em.findOneByOrFail(Counter, { key })
            if (fail) throw new Error("summani tekshirish yiqildi")
            return (await em.save(Invoice, { number: `${year}-${String(value).padStart(5, "0")}`, amount })).number
        })
    }
}

