import { Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, PrimaryGeneratedColumn } from "typeorm"

@Entity() class Order { @PrimaryGeneratedColumn() id: number; @Column() note: string }
@Entity() class Payment { @PrimaryGeneratedColumn() id: number; @Column() amount: number }

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Order, Payment], synchronize: true })] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const ds = app.get(DataSource)
    const payFails = async () => { throw new Error("to'lov yiqildi") }
    // ❌ xato ichkarida ushlandi — tranzaksiya "muvaffaqiyatli" tugaydi
    await ds.transaction(async em => {
        await em.save(Order, { note: "❌ to'lovsiz buyurtma" })
        try { await payFails() } catch (e) { console.log("  ushlandi:", (e as Error).message) }
    })
    // ✔ xato tashqariga chiqadi — rollback
    await ds.transaction(async em => {
        await em.save(Order, { note: "✔ bekor bo'ladi" })
        await payFails()
    }).catch(e => console.log("  tashqarida:", e.message))
    console.log("buyurtmalar:", (await ds.getRepository(Order).find()).map(o => o.note), "| to'lovlar:", await ds.getRepository(Payment).count())
    await app.close()
}
