import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, PrimaryGeneratedColumn } from "typeorm"

@Entity() class Order { @PrimaryGeneratedColumn() id: number; @Column() total: number; @Column() status: string }

const gateway = {
    log: [] as string[],
    charge(amount: number) { this.log.push(`charge ${amount}`); return `ch_${this.log.length}` },
    refund(id: string) { this.log.push(`refund ${id}`) },
}

@Injectable()
class CheckoutService {
    constructor(private readonly ds: DataSource) {}
    async checkout(total: number, failDb = false) {
        const chargeId = gateway.charge(total) // tashqi — tranzaksiyaga kirmaydi
        try {
            return await this.ds.transaction(async em => {
                const o = await em.save(Order, { total, status: "paid" })
                if (failDb) throw new Error("ombor yetmadi")
                return o.id
            })
        } catch (e) {
            gateway.refund(chargeId) // kompensatsiya
            throw e
        }
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Order], synchronize: true })], providers: [CheckoutService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const s = app.get(CheckoutService)
    await s.checkout(50000)
    await s.checkout(18000, true).catch(e => console.log("✗", e.message))
    console.log("shlyuz:", gateway.log, "| buyurtmalar:", await app.get(DataSource).getRepository(Order).count())
    await app.close()
}
main()

