import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { AsyncLocalStorage } from "node:async_hooks"
import { Column, DataSource, Entity, EntityManager, PrimaryGeneratedColumn } from "typeorm"

@Entity() class Order { @PrimaryGeneratedColumn() id: number; @Column() total: number }
@Entity() class Stock { @PrimaryGeneratedColumn() id: number; @Column() qty: number }

const als = new AsyncLocalStorage<EntityManager>()

@Injectable()
class TxHost {
    constructor(private readonly ds: DataSource) {}
    get em() { return als.getStore() ?? this.ds.manager }
    run<T>(fn: () => Promise<T>) { return this.ds.transaction(em => als.run(em, fn)) }
}

@Injectable() class StockService {
    constructor(private readonly tx: TxHost) {}
    async take(qty: number) {
        await this.tx.em.decrement(Stock, { id: 1 }, "qty", qty)
        if ((await this.tx.em.findOneByOrFail(Stock, { id: 1 })).qty < 0) throw new Error("ombor yetmadi")
    }
}
@Injectable() class OrdersService {
    constructor(private readonly tx: TxHost, private readonly stock: StockService) {}
    place(total: number, qty: number) {
        return this.tx.run(async () => { await this.tx.em.save(Order, { total }); await this.stock.take(qty) })
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Order, Stock], synchronize: true })], providers: [TxHost, StockService, OrdersService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const ds = app.get(DataSource)
    await ds.getRepository(Stock).save({ qty: 5 })
    const s = app.get(OrdersService)
    await s.place(50000, 3)
    await s.place(90000, 4).catch(e => console.log("✗", e.message))
    console.log("buyurtmalar:", await ds.getRepository(Order).count(), "| ombor:", (await ds.getRepository(Stock).findOneBy({ id: 1 }))!.qty)
    await app.close()
}
main()

