@Entity() class Product { @PrimaryGeneratedColumn() id: number; @Column() name: string; @Column() price: number }

@Injectable()
class ImportService {
    constructor(private readonly ds: DataSource) {}
    import(rows: { name: string; price: number }[]) {
        return this.ds.transaction(async em => {
            for (const [i, r] of rows.entries()) {
                if (!(r.price > 0)) throw new Error(`${i + 1}-qator: narx noto'g'ri (${r.price})`)
                await em.save(Product, r)
            }
            return rows.length
        })
    }
}

