import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, EntityManager, PrimaryGeneratedColumn } from "typeorm"

@Entity() class User { @PrimaryGeneratedColumn() id: number; @Column({ unique: true }) email: string }
const outbox: string[] = []

@Injectable()
class UnitOfWork {
    constructor(private readonly ds: DataSource) {}
    async run<T>(work: (em: EntityManager, afterCommit: (fn: () => void) => void) => Promise<T>) {
        const hooks: (() => void)[] = []
        const result = await this.ds.transaction(em => work(em, fn => hooks.push(fn)))
        hooks.forEach(h => h()) // faqat commit muvaffaqiyatli bo'lsa
        return result
    }
}

@Injectable()
class RegisterService {
    constructor(private readonly uow: UnitOfWork) {}
    register(email: string) {
        return this.uow.run(async (em, afterCommit) => {
            afterCommit(() => outbox.push(`xush kelibsiz → ${email}`))
            await em.save(User, { email })
        })
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [User], synchronize: true })], providers: [UnitOfWork, RegisterService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const s = app.get(RegisterService)
    await s.register("ali@mail.uz")
    await s.register("ali@mail.uz").catch(() => console.log("✗ takroriy email — tranzaksiya bekor"))
    console.log("yuborilgan xatlar:", outbox)
    await app.close()
}
