import { BadRequestException, Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, PrimaryGeneratedColumn } from "typeorm"

@Entity() class Entry { @PrimaryGeneratedColumn() id: number; @Column() txId: string; @Column() account: string; @Column() amount: number }

@Injectable()
class LedgerService {
    constructor(private readonly ds: DataSource) {}
    post(txId: string, lines: { account: string; amount: number }[]) {
        const sum = lines.reduce((s, l) => s + l.amount, 0)
        if (sum !== 0) throw new BadRequestException(`Jurnal muvozanatda emas: ${sum}`)
        return this.ds.transaction(em => em.save(Entry, lines.map(l => ({ ...l, txId }))))
    }
    balances() {
        return this.ds.query("SELECT account, SUM(amount) AS balance FROM entry GROUP BY account ORDER BY account")
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Entry], synchronize: true })], providers: [LedgerService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const s = app.get(LedgerService)
    await s.post("t1", [{ account: "kassa", amount: 50000 }, { account: "savdo", amount: -50000 }])
    await s.post("t2", [{ account: "kassa", amount: -12000 }, { account: "xarajat", amount: 12000 }])
    try { await s.post("t3", [{ account: "kassa", amount: 100 }]) } catch (e) { console.log("✗", (e as Error).message) }
    console.table(await s.balances())
    await app.close()
}
