import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, PrimaryGeneratedColumn } from "typeorm"

@Entity() class Movement { @PrimaryGeneratedColumn() id: number; @Column() account: string; @Column() amount: number; @Column() at: string }

@Injectable()
class TransferService {
    constructor(private readonly ds: DataSource) {}
    transfer(from: string, to: string, amount: number, now = new Date("2025-05-01T10:00:00.000Z")) {
        const at = now.toISOString() // bir marta olinadi
        return this.ds.transaction(async em => {
            await em.save(Movement, { account: from, amount: -amount, at })
            await new Promise(r => setTimeout(r, 5)) // oraliqda vaqt o'tdi
            await em.save(Movement, { account: to, amount, at })
        })
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Movement], synchronize: true })], providers: [TransferService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    await app.get(TransferService).transfer("Ali", "Vali", 25000)
    console.log(await app.get(DataSource).query("SELECT account, amount, at FROM movement"))
    await app.close()
}
main()

import { Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, PrimaryGeneratedColumn } from "typeorm"

@Entity() class Post { @PrimaryGeneratedColumn() id: number; @Column() likes: number }

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Post], synchronize: true })] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const repo = app.get(DataSource).getRepository(Post)
    await repo.save([{ likes: 0 }, { likes: 0 }])
    const naiveLike = async (id: number) => {
        const p = (await repo.findOneBy({ id }))!
        await new Promise(r => setTimeout(r, 5)) // boshqa so'rov shu orada o'qiydi
        await repo.update(id, { likes: p.likes + 1 })
    }
    await Promise.all(Array.from({ length: 5 }, () => naiveLike(1)))
    await Promise.all(Array.from({ length: 5 }, () => repo.increment({ id: 2 }, "likes", 1)))
    console.log("o'qib-yozish:", (await repo.findOneBy({ id: 1 }))!.likes, "/ 5 | increment:", (await repo.findOneBy({ id: 2 }))!.likes, "/ 5")
    await app.close()
}
main()

import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, PrimaryGeneratedColumn, VersionColumn } from "typeorm"

@Entity() class Stock { @PrimaryGeneratedColumn() id: number; @Column() qty: number; @VersionColumn() version: number }

@Injectable()
class StockService {
    constructor(private readonly ds: DataSource) {}
    async take(id: number, qty: number, onRead?: () => Promise<void>) {
        for (let attempt = 1; attempt <= 3; attempt++) {
            const s = (await this.ds.getRepository(Stock).findOneBy({ id }))!
            await onRead?.()
            const res = await this.ds.getRepository(Stock).update({ id, version: s.version }, { qty: s.qty - qty, version: s.version + 1 })
            if (res.affected) return `✓ ${attempt}-urinishda, qoldi ${s.qty - qty}`
            console.log(`  ${attempt}-urinish: version ${s.version} eskirgan, qayta o'qiyapmiz`)
            onRead = undefined
        }
        throw new Error("to'qnashuv davom etyapti")
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Stock], synchronize: true })], providers: [StockService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const repo = app.get(DataSource).getRepository(Stock)
    await repo.save({ qty: 10 })
    const s = app.get(StockService)
    // o'qigandan keyin boshqa foydalanuvchi 2 ta oldi
    console.log(await s.take(1, 3, async () => { await repo.update(1, { qty: 8, version: 2 }) }))
    await app.close()
}
main()

import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

const MIN = 60_000

@Injectable()
class SeatsService {
    private holds = new Map<string, { user: string; until: number }>()
    private sold = new Set<string>()
    hold(seat: string, user: string, now: number) {
        const h = this.holds.get(seat)
        if (this.sold.has(seat) || (h && h.until > now && h.user !== user)) return `✗ ${seat} band`
        this.holds.set(seat, { user, until: now + 10 * MIN })
        return `✓ ${user} ${seat} ni 10 daqiqaga band qildi`
    }
    pay(seat: string, user: string, now: number) {
        const h = this.holds.get(seat)
        if (!h || h.user !== user || h.until <= now) return `✗ ${user}: bron muddati o'tgan`
        this.sold.add(seat); this.holds.delete(seat)
        return `✓ ${user} ${seat} uchun to'ladi`
    }
}

@Module({ providers: [SeatsService] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const s = app.get(SeatsService)
    const t = Date.parse("2025-05-01T19:00:00Z")
    console.log(s.hold("12A", "Ali", t))
    console.log(s.hold("12A", "Vali", t + 3 * MIN))
    console.log(s.hold("12A", "Vali", t + 11 * MIN))
    console.log(s.pay("12A", "Ali", t + 12 * MIN))
    console.log(s.pay("12A", "Vali", t + 13 * MIN))
    await app.close()
}
main()

import { Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { BeforeInsert, Column, DataSource, Entity, PrimaryGeneratedColumn } from "typeorm"

@Entity() class Order { @PrimaryGeneratedColumn() id: number; @Column() total: number }
@Entity() class Line {
    @PrimaryGeneratedColumn() id: number
    @Column() qty: number
    @BeforeInsert() check() { if (this.qty <= 0) throw new Error(`qty=${this.qty} bo'lishi mumkin emas`) }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Order, Line], synchronize: true })] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const ds = app.get(DataSource)
    await ds.transaction(async em => {
        await em.save(Order, { total: 50000 })
        await em.save(em.create(Line, [{ qty: 2 }, { qty: 0 }])) // create() — hook'lar faqat entity instance'da ishlaydi
    }).catch(e => console.log("✗", e.message))
    console.log("buyurtmalar:", await ds.getRepository(Order).count(), "| qatorlar:", await ds.getRepository(Line).count())
    await app.close()
}
main()

function lockOrder(fromId: number, toId: number) {
    return [fromId, toId].sort((a, b) => a - b)
}

// Ikki parallel o'tkazma: A→B va B→A
const t1 = lockOrder(1, 2)
const t2 = lockOrder(2, 1)
console.log("A→B qulflaydi:", t1.join(" keyin "))
console.log("B→A qulflaydi:", t2.join(" keyin "))
console.log(t1.join() === t2.join()
    ? "✓ ikkalasi bir tartibda — biri kutadi, deadlock bo'lmaydi"
    : "✗ tartib har xil — deadlock xavfi")
