import { BadRequestException, Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, PrimaryGeneratedColumn } from "typeorm"

@Entity() class Payment { @PrimaryGeneratedColumn() id: number; @Column() amount: number; @Column({ default: 0 }) refunded: number }
@Entity() class Refund { @PrimaryGeneratedColumn() id: number; @Column() paymentId: number; @Column() amount: number }

@Injectable()
class RefundService {
    constructor(private readonly ds: DataSource) {}
    refund(paymentId: number, amount: number) {
        return this.ds.transaction(async em => {
            const p = await em.findOneByOrFail(Payment, { id: paymentId })
            if (p.refunded + amount > p.amount) throw new BadRequestException(`Qaytarish mumkin: ${p.amount - p.refunded}, so'raldi: ${amount}`)
            await em.save(Refund, { paymentId, amount })
            await em.increment(Payment, { id: paymentId }, "refunded", amount)
            return `✓ ${amount} qaytarildi (jami ${p.refunded + amount}/${p.amount})`
        })
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Payment, Refund], synchronize: true })], providers: [RefundService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    await app.get(DataSource).getRepository(Payment).save({ amount: 100000 })
    const s = app.get(RefundService)
    for (const a of [30000, 50000, 30000]) {
        try { console.log(await s.refund(1, a)) } catch (e) { console.log("✗", (e as Error).message) }
    }
    await app.close()
}
main()

import { Injectable, Module } from "@nestjs/common"
