@Entity() class Coupon { @PrimaryColumn() code: string; @Column({ default: false }) used: boolean; @Column({ type: "integer", nullable: true }) usedBy: number | null }

@Injectable()
class CouponService {
    constructor(private readonly ds: DataSource) {}
    async redeem(code: string, userId: number) {
        const res = await this.ds.getRepository(Coupon).update({ code, used: false }, { used: true, usedBy: userId })
        return res.affected ? `✓ user#${userId} kuponni ishlatdi` : `✗ user#${userId}: kupon allaqachon ishlatilgan`
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Coupon], synchronize: true })], providers: [CouponService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    await app.get(DataSource).getRepository(Coupon).save({ code: "OSH50", usedBy: null })
    const s = app.get(CouponService)
    console.log(await Promise.all([s.redeem("OSH50", 1), s.redeem("OSH50", 2)]))
    await app.close()
}
