import { Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { getDataSourceToken, TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, PrimaryGeneratedColumn } from "typeorm"

@Entity() class Order { @PrimaryGeneratedColumn() id: number; @Column() total: number }
@Entity() class Analytics { @PrimaryGeneratedColumn() id: number; @Column() event: string }

@Module({
    imports: [
        TypeOrmModule.forRoot({ type: "sqljs", entities: [Order], synchronize: true }),
        TypeOrmModule.forRoot({ name: "analytics", type: "sqljs", entities: [Analytics], synchronize: true }),
    ],
})
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const main = app.get(DataSource)
    const analytics = app.get<DataSource>(getDataSourceToken("analytics"))
    await main.transaction(em => em.save(Order, { total: 50000 }))
    await analytics.transaction(async em => { await em.save(Analytics, { event: "order.created" }); throw new Error("analytics bazasi yiqildi") }).catch(e => console.log("✗", e.message))
    console.log("orders:", await main.getRepository(Order).count(), "| analytics:", await analytics.getRepository(Analytics).count())
    console.log("→ yechim: outbox yoki kompensatsiya (saga)")
    await app.close()
}
main()

