import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, DeleteDateColumn, Entity, PrimaryGeneratedColumn } from "typeorm"

@Entity() class Customer { @PrimaryGeneratedColumn() id: number; @Column() name: string; @DeleteDateColumn() deletedAt: Date | null }
@Entity() class AuditLog { @PrimaryGeneratedColumn() id: number; @Column() message: string }

@Injectable()
class CustomersService {
    constructor(private readonly ds: DataSource) {}
    remove(id: number, by: string, auditFails = false) {
        return this.ds.transaction(async em => {
            await em.softDelete(Customer, id)
            if (auditFails) throw new Error("audit jadvaliga yozib bo'lmadi")
            await em.save(AuditLog, { message: `${by} mijoz #${id} ni o'chirdi` })
        })
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Customer, AuditLog], synchronize: true })], providers: [CustomersService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const ds = app.get(DataSource)
    await ds.getRepository(Customer).save([{ name: "Ali" }, { name: "Vali" }])
    const s = app.get(CustomersService)
    await s.remove(1, "admin")
    await s.remove(2, "admin", true).catch(e => console.log("✗", e.message))
    console.log("faol mijozlar:", (await ds.getRepository(Customer).find()).map(c => c.name), "| audit:", (await ds.getRepository(AuditLog).find()).map(a => a.message))
    await app.close()
}
main()

import { BadRequestException, Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, PrimaryGeneratedColumn } from "typeorm"

@Entity() class Account { @PrimaryGeneratedColumn() id: number; @Column() balance: number; @Column({ default: "open" }) status: string }
@Entity() class Order { @PrimaryGeneratedColumn() id: number; @Column() accountId: number; @Column() status: string }

@Injectable()
class AccountsService {
    constructor(private readonly ds: DataSource) {}
    close(id: number) {
        return this.ds.transaction(async em => {
            const acc = await em.findOneByOrFail(Account, { id })
            if (acc.balance !== 0) throw new BadRequestException(`Balans ${acc.balance} — avval yechib oling`)
            const open = await em.countBy(Order, { accountId: id, status: "pending" })
            if (open) throw new BadRequestException(`${open} ta ochiq buyurtma bor`)
            await em.update(Account, id, { status: "closed" })
            return `✓ hisob #${id} yopildi`
        })
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Account, Order], synchronize: true })], providers: [AccountsService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const ds = app.get(DataSource)
    await ds.getRepository(Account).save([{ balance: 5000 }, { balance: 0 }, { balance: 0 }])
    await ds.getRepository(Order).save({ accountId: 2, status: "pending" })
    const s = app.get(AccountsService)
    for (const id of [1, 2, 3]) {
        try { console.log(await s.close(id)) } catch (e) { console.log(`✗ #${id}:`, (e as Error).message) }
    }
    await app.close()
}
main()

import { Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { Column, DataSource, Entity, PrimaryGeneratedColumn } from "typeorm"

@Entity() class Product { @PrimaryGeneratedColumn() id: number; @Column() price: number; @Column({ default: false }) repriced: boolean }

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Product], synchronize: true })] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const ds = app.get(DataSource)
    for (let k = 0; k < 4; k++) await ds.getRepository(Product).insert(Array.from({ length: 250 }, (_, i) => ({ price: 1000 + k * 250 + i })))
    let batches = 0
    while (true) {
        const n = await ds.transaction(async em => {
            await em.query("UPDATE product SET price = price * 11 / 10, repriced = 1 WHERE id IN (SELECT id FROM product WHERE repriced = 0 ORDER BY id LIMIT 300)")
            const [{ n }] = await em.query("SELECT changes() AS n")
            return n as number
        })
        if (!n) break
        batches++
    }
    const [{ done }] = await ds.query("SELECT COUNT(*) AS done FROM product WHERE repriced = 1")
    console.log(`${batches} ta qisqa tranzaksiya, yangilandi: ${done}`)
    await app.close()
}
main()
